(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c33"]=[{"id":"00005611","register_sub_id":"101","register_pk":"106599","name":"貞照寺門","kana":"ていしょうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.407303,"lng":136.959946,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、銅板葺、面積29㎡","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0098","desc":"入母屋造，銅板葺，正面と背面に千鳥破風，軒唐破風を付けた八脚門で，仁王像を安置する。軸部は円柱を貫で固め，出組の詰組，軒支輪付で，二軒隅扇垂木とする。内法貫上は精緻な彫物欄間で飾る。調和のとれた外観で，細部も充実し，境内東の正面に相応しい門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005611"},{"id":"00014827","register_sub_id":"101","register_pk":"519085","name":"南宮大社斎館御炊屋","kana":"なんぐうたいしゃさいかんおすいや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.36022222,"lng":136.52676389,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0302","desc":"御炊屋は北棟の北東に渡廊下で接続する切妻造平入桟瓦葺の東西棟。間取りは南に廊下を通し、その北に同規模の部屋を東西に２室並べ、各室南半は板床、北半は土間の台所とし、北面に窓と戸口を開ける。披露宴に欠かせない炊事施設で、斎館北東の構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014827"},{"id":"00014828","register_sub_id":"101","register_pk":"519086","name":"南宮大社斎館回廊","kana":"なんぐうたいしゃさいかんかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.36000278,"lng":136.52642778,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造、瓦葺、建築面積20㎡","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0303","desc":"南庭を囲う回廊は切妻造桟瓦葺の単廊。北棟南面西寄りと南棟西端を連絡する内向きの動線で、南庭の南西に矩折れに廻り、南庭側を吹き放つ。外壁の南面は真壁で漆喰仕上とし、西面は連子窓を開けて、腰と内法に長押を打ち、斎館の格式ある表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014828"},{"id":"00014825","register_sub_id":"101","register_pk":"519083","name":"南宮大社斎館北棟","kana":"なんぐうたいしゃさいかんきたとう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.36015556,"lng":136.52659167,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造2階建、瓦葺、建築面積380㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0300","desc":"境内東端に西面して建つ北棟は、二階建切妻造の東西棟で、正面に片流れの車寄を付す。内部は中廊下を通し、南に大広間、北に控の間を各二室一対で配す。二階西室は西に祭壇を設けた儀式殿の間で格天井を張り、祭壇廻りを錺金具で荘厳した華やかな婚礼施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014825"},{"id":"00014826","register_sub_id":"101","register_pk":"519084","name":"南宮大社斎館南棟","kana":"なんぐうたいしゃさいかんみなみとう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.35998333,"lng":136.52665,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0301","desc":"南棟は平屋建切妻造桟瓦葺の東西棟で北面東寄りを北へ延ばし北棟と接続。内部は中庭沿いに片廊下を廻らし、西から座敷２室、神職の潔斎用風呂、東端を管理人室、北に座敷２室を配す。座敷境の欄間は杉板に梅や竹などを透彫とし、婚礼の華やかさを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014826"},{"id":"00007037","register_sub_id":"101","register_pk":"108019","name":"法誓寺本堂","kana":"ほうせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県加茂郡八百津町久田見2757","lat":35.520515,"lng":137.189377,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積819㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0165","desc":"境内中央に東面して建つ。桁行２６ｍ梁間２５ｍに及ぶ大規模な仏堂。入母屋造桟瓦葺で、正面に３間向拝を付ける。正・側面に広縁と落縁を設け、内部は外陣と矢来内、内陣からなる浄土真宗独特の平面になる。外陣を小組格天井とするなど入念なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007037"},{"id":"00015456","register_sub_id":"101","register_pk":"533471","name":"小梳神社拝殿及び幣殿","kana":"おぐしじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県静岡市葵区紺屋町7-13","lat":34.97355833,"lng":138.38634444,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積147㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"22 - 0342","desc":"本殿前面に建つ鉄筋コンクリート造社殿。南から下拝殿、上拝殿、幣殿とし、下拝殿は入母屋造向拝付で両側に下屋を付し、幣殿左右に祭器殿と神饌殿を張出し全体エ字形平面とする。幣殿を含め屋根を重ねた抑揚感ある外観を呈する。戦後間もない耐火構造の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015456"},{"id":"00015455","register_sub_id":"101","register_pk":"533470","name":"小梳神社本殿","kana":"おぐしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県静岡市葵区紺屋町7-13","lat":34.97366111,"lng":138.38641389,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積20㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"22 - 0341","desc":"市街地中心部の境内奥に南面する、建ちの高い鉄筋コンクリート造の一間社。切妻造平入銅板葺で、正側面に高欄付縁を廻らし脇障子を建てる。組物は平三斗で、頭貫に大仏様風の特異な木鼻を付す。軒廻りや妻部を含めコンクリートにより丁寧に造形された社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015455"},{"id":"00010307","register_sub_id":"101","register_pk":"199080","name":"可睡斎瑞龍閣","kana":"かすいさいずいりゅうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県袋井市久能2915-1","lat":34.774365,"lng":137.920128,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺及び銅板葺、建築面積638㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"22-0198","desc":"木造二階建、妻入り、入母屋造桟瓦葺で下屋を廻らし、正面に唐破風玄関を構える。一階は大振りな座敷飾を備えた六間取、二階は大広間の周囲に畳廊下を廻らし、各室ごとに異なる主題に因む欄間や絵襖で華やかに飾る。規模雄大で優美な内装をもつ迎賓施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010307"},{"id":"00010308","register_sub_id":"101","register_pk":"199081","name":"可睡斎東司","kana":"かすいさいとうす","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県袋井市久能2915-1","lat":34.774479,"lng":137.919985,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"22-0199","desc":"約八メートル四方の規模をもつ東司で、南辺に小便器、北東面に大便器室を並べ、中央の壇上に烏枢沙摩明王を祀る。天井は周囲に吹寄せの格縁を廻らして内側に網代天井を張り、中央に天蓋風の飾りを設ける。欄間に組子細工を飾るなど、風雅な意匠を持つ東司。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010308"},{"id":"00011960","register_sub_id":"101","register_pk":"354923","name":"旧東泉院宝蔵","kana":"きゅうとうせんいんほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県富士市今泉八丁目1428-1","lat":35.166707,"lng":138.686666,"geo_status":"db","era":"安政4年（1857）","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"22-242","desc":"旧東泉院境内に南面して建つ。桁行七・三メートル梁間四・五メートル、土蔵造二階建、切妻造で、南面に下屋を設けて戸口を開き、二階に窓を設ける。外壁は漆喰塗で鉢巻を廻らし、南面の腰を海鼠壁、他を簓子下見板張とする。富士修験に係る東泉院唯一の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011960"},{"id":"00002546","register_sub_id":"101","register_pk":"103536","name":"清水寺庫裏","kana":"きよみずでらくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区音羽町27-8","lat":34.979099,"lng":138.396683,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積249㎡","structure_material":"木造平屋一部2階建","registered":"2001.11.20(平成13.11.20)","register_no":"22 － 0077","desc":"鉄筋コンクリート造本堂の南東方に建つ。入母屋造玄関をもつ木造平屋建，入母屋造，妻入の庫裏と木造２階建，寄棟造の奥書院から成る。庫裏の北側には西から８畳規模の応接室，８畳，１０畳の表書院を並べる。本堂と同じ古宇田實の設計による近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002546"},{"id":"00001710","register_sub_id":"101","register_pk":"102700","name":"清水寺鐘楼","kana":"きよみずでらしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市葵区音羽町27-8","lat":34.979588,"lng":138.396225,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0068","desc":"方一間、四方吹き放しの鐘台で、屋根は入母屋造、本瓦葺とする。本柱と間柱上に尾垂木付の組物を置いて華やかな軒廻りとする。青銅鋳物製の隅支柱に蓮をモチーフとする意匠を施し、蟇股や木鼻の意匠にも特色がある。設計は東京美術学校の古宇田實。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001710"},{"id":"00001112","register_sub_id":"101","register_pk":"102102","name":"清水寺本堂","kana":"きよみずでらほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区音羽町27-8","lat":34.97925962,"lng":138.39652784,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積186㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"22 － 0040","desc":"清水山公園に隣接した境内地に建つ鉄筋コンクリート造の本堂。正面７間に円柱を配し、中央３間は二手先として向拝風に切り上げた軒を支える。設計は神戸高等工業学校長古宇田実で、東京の島藤が請負った。切妻屋根を持つ特異な形態の本堂として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001112"},{"id":"00010305","register_sub_id":"101","register_pk":"199078","name":"玄妙寺経蔵","kana":"げんみょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県磐田市見付字西坂2598","lat":34.727044,"lng":137.856033,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積13㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"22-0196","desc":"境内南東隅に西面して建ち、鉄筋コンクリート造、切妻造セメント瓦葺である。外壁は人造石洗出しで、柱形や軒蛇腹を表し、石造風に化粧目地を切る。正面に扉口、北面に窓を設けて庇を付け、鉄扉を開く。耐火性を重視した、戦前のコンクリート造経蔵の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010305"},{"id":"00010306","register_sub_id":"101","register_pk":"199079","name":"玄妙寺門柱及び塀","kana":"げんみょうじもんちゅうおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市見付字玄妙小路2440-1他","lat":34.72705201,"lng":137.85561599,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、延長16m","structure_material":"土塀","registered":"2014.12.19(平成26.12.19)","register_no":"22-0197","desc":"境内西辺を画す門柱と土塀で、いずれも三和土を成型した中空ブロックを積む。門柱は五段積として頂部に宝形造屋根を載せ、土塀は版築基礎上に四段布積し、同じ三和土で切妻屋根を造る。左官技法を駆使した独特な構造の門塀で、当地の建築技術を伝える希少例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010306"},{"id":"00001517","register_sub_id":"101","register_pk":"102507","name":"光長寺御宝蔵","kana":"こうちょうじごほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県沼津市岡宮1055","lat":35.12821517,"lng":138.87498897,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積41㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"22 － 0062","desc":"法華宗大本山光長寺境内の東北隅に建つ鉄筋コンクリート造の六角堂。銅板葺の屋根は尖塔状に反り上がり，モルタルで造られた虹梁・木鼻・蟇股・大瓶束が向拝柱，外壁を飾る。モルタルの外装材としての可能性を示した作品。設計は金田恭介，施工は内田金五郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001517"},{"id":"00011137","register_sub_id":"101","register_pk":"205244","name":"松蔭寺開山堂","kana":"しょういんじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県沼津市原字東畑128-1","lat":35.123299,"lng":138.800171,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積19㎡","structure_material":"石造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0222","desc":"境内南寄りに建ち、坐禅堂を接続する。一辺二・七メートルの六角形平面で屋根は六注の桟瓦葺とし、露盤上に宝珠を飾る。壁体は伊豆石積で内外ともに漆喰仕上げとし、石製の軒蛇腹を廻らす。内部は須弥壇を設け、白隠像を祀る。独自性の高い構造形式をもつ堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011137"},{"id":"00011138","register_sub_id":"101","register_pk":"205245","name":"松蔭寺山門","kana":"しょういんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県沼津市原字東畑128-1","lat":35.123932,"lng":138.800309,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0223","desc":"境内北正面で旧東海道に向かって構える、間口三・〇メートルの一間薬医門、切妻造石瓦葺である。五平の本柱に冠木を渡し、控柱筋では差物と桁を重ねて堅固に組む。石瓦は長さ一メートルの伊豆石切石を三段に葺く。古刹の門前を特徴付ける希少な屋根の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011138"},{"id":"00000249","register_sub_id":"101","register_pk":"101239","name":"真珠院鐘楼","kana":"しんじゅいんしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市清水区梅ヶ谷608","lat":35.04490945,"lng":138.45085274,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造，建築面積26㎡","structure_material":"鉄筋コンクリート造","registered":"1997.07.15(平成9.07.15)","register_no":"22 － 0004","desc":"鉄筋コンクリート造の鐘楼。基壇上に袴腰や縁を取り付け、柱や長押㎡垂木等にペイント塗装を施す。袴腰の部分に鐘楼建造の由来を刻した石版をはめ込む。設計及び施工は市内の桜井康弘。寺院景観を構成する要素として訪れる人に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000249"},{"id":"00001617","register_sub_id":"101","register_pk":"102607","name":"大中寺恩香殿","kana":"だいちゅうじおんこうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県沼津市中沢田457","lat":35.12288621,"lng":138.85432566,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0064","desc":"大中寺は沼津市郊外に位置する梅園で名高い臨済宗寺院であり，恩香殿は沼津御用邸に滞在中の皇族の観梅などの際の休息所として建築された。広間と前室の三方に広縁を廻し，広間背後に茶室を設ける。敷地の高低差を活かし庭園と一体的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001617"},{"id":"00001618","register_sub_id":"101","register_pk":"102608","name":"大中寺通玄橋","kana":"だいちゅうじつうげんばし","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県沼津市中沢田457","lat":35.12276328,"lng":138.85437166,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、橋長6m","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0065","desc":"庫裏から恩香殿の南妻側に通じる太鼓橋風の渡り廊下で，切妻造の屋根を架ける。高欄や垂れ壁などのデザインに特色がある。庫裏の建て替えに伴ってわずかに位置を変更しているが，恩香殿と同時期の建築であり一体の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001618"},{"id":"00013117","register_sub_id":"101","register_pk":"368376","name":"大福寺庫裏","kana":"だいふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区三ヶ日町福長字寺中219","lat":34.82928056,"lng":137.54970278,"geo_status":"db","era":"大正後期／昭和20年代移築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積308㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"22 － 0282","desc":"製糸工場の事務所兼迎賓館を移築し庫裏としたもの。建ちの高い二階建で、一階は正面中央に入母屋造の玄関を据え、中廊下を通し南北に上質な座敷を並べ、外周部に縁を廻す。土間や根太天井等の民家の特性を示し、大正期の製糸工場の一端を伝える近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013117"},{"id":"00012916","register_sub_id":"101","register_pk":"368098","name":"方広寺行在所","kana":"ほうこうじあんざいしょ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84903889,"lng":137.61545278,"geo_status":"db","era":"明治元年／明治18年移築・改修、昭和前期改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 266","desc":"新居宿本陣・飯田家の明治天皇行在所を移築したもので、三笑閣北方に南面して建つ。寄棟造桟瓦葺妻入。四周に下屋を廻し、正面西端に起り屋根の玄関、東側面北端に茶室を付す。南に24畳の次の間、北に上段の間を配する。格式を備えた上質な書院建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012916"},{"id":"00012919","register_sub_id":"101","register_pk":"368101","name":"方広寺開山堂","kana":"ほうこうじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84838056,"lng":137.61428056,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 269","desc":"観音堂の西側に南面して建つ。桁行3間梁間3間、入母屋造本瓦葺。各面に両折桟唐戸と花頭窓を設ける。内部は土間四半敷で、背面中央に拝所を出して昭堂に接続する。組物は尾垂木付二手先の詰組、中備は間斗束、妻飾は虹梁大瓶束。華麗な佇まいの礼拝施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012919"},{"id":"00012925","register_sub_id":"101","register_pk":"368107","name":"方広寺神楽堂","kana":"ほうこうじかぐらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84799444,"lng":137.61426944,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 275","desc":"半僧坊拝殿の南方に北面して建つ平屋建、正面吹放しの土間舞台。一軒疎垂木、入母屋造桟瓦葺。南面に下屋で幅半間の上段を通し、格天井、壁縦板張とする。東面にある切妻造の控室は化粧屋根裏、内壁漆喰塗。水屋とともに半僧坊前の祭礼空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012925"},{"id":"00012918","register_sub_id":"101","register_pk":"368100","name":"方広寺観音堂","kana":"ほうこうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84843889,"lng":137.61443889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 268","desc":"本堂の西側に南面して建つ。正面1間側背面2間、宝形造桟瓦葺で、両側面前半に張出し部を設け、正面に擬宝珠高欄付の切目縁を通す。内部は竿縁天井の一室で、後方に仏壇を設けて観音菩薩像を安置する。小規模ながら均整の取れた外観で境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012918"},{"id":"00012928","register_sub_id":"101","register_pk":"368110","name":"方広寺三重塔","kana":"ほうこうじさんじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84738333,"lng":137.61625278,"geo_status":"db","era":"大正12年／昭和中期増築、平成11年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造三重塔、瓦葺、建築面積11㎡、門塀付","structure_material":"木造三重塔","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 278","desc":"本堂の南方、沢を隔てた山頂に西面して建つ。各重とも方3間、組物は尾垂木付三手先、二軒繁垂木、本瓦葺である。乱石積基壇の正面中央を突出して切妻造の棟門を構え、四周に板塀を廻す。もと京都府技手・安井楢次郎の設計で、古典的な和様の構成をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012928"},{"id":"00012914","register_sub_id":"101","register_pk":"368096","name":"方広寺三笑閣","kana":"ほうこうじさんしょうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84868611,"lng":137.61552778,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部地下１階建、瓦葺、建築面積524㎡","structure_material":"木造2階一部地下１階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 264","desc":"大庫裡の東側に接続する接客施設。入母屋造桟瓦葺二階建を東西に並べ、東を南北棟、西を東西棟とする。2階は各大座敷で、1階は東に小座敷、西に厨房と水場を配し、両棟間には食堂を設ける。大庫裡とともに大本山にふさわしい広壮な接客空間を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012914"},{"id":"00012929","register_sub_id":"101","register_pk":"368111","name":"方広寺山門","kana":"ほうこうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84878611,"lng":137.61784444,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 279","desc":"本堂の南東方、沢沿いの参道上に南面して建つ。入母屋造本瓦葺の三間一戸二重門で、組物は下層を出組、上層を尾垂木付二手先、中備は間斗束、中央間を双斗とする。妻飾は虹梁大瓶束。軒は二軒繁垂木。精緻なつくりで、格式ある大本山の表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012929"},{"id":"00012911","register_sub_id":"101","register_pk":"368093","name":"方広寺知客寮","kana":"ほうこうじしかりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84861389,"lng":137.61500833,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 261","desc":"本堂の東面北端に接続する役僧の詰所。南北棟の入母屋造桟瓦葺、二軒疎垂木で、南に本堂と大庫裡をつなぐ幅二間の廊下を通し、北に14畳座敷と6畳控室、物置を配して東北二面に縁を廻す。本堂、大庫裡と並び建ち、境内中心部の壮大な景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012911"},{"id":"00012927","register_sub_id":"101","register_pk":"368109","name":"方広寺七尊菩薩堂拝殿","kana":"ほうこうじしちそんぼさつどうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84776944,"lng":137.61442222,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 277","desc":"本堂の南西方、沢を隔てた山腹に東面して建つ。桁行3間梁間2間、切妻造桟瓦葺、壁縦板張で、正面中央間に出入口を設ける。内部は板敷、竿縁天井とする。背面中央間を開放して覆屋内に安置する流造の七尊菩薩堂を臨み、神前に静謐な礼拝空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012927"},{"id":"00012915","register_sub_id":"101","register_pk":"368097","name":"方広寺宗務本院","kana":"ほうこうじしゅうむほんいん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84905278,"lng":137.61544167,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 265","desc":"大庫裡北側の高台に南面して建つ宗務総長の執務室。切妻造桟瓦葺の平屋建で、西南北三面に下屋を廻し、渡廊下で大庫裡に接続する。前後2列6室を配して西北隅を座敷とし、西北二面に縁を廻す。知客寮、大庫裡とともに大本山の寺務空間の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012915"},{"id":"00012920","register_sub_id":"101","register_pk":"368102","name":"方広寺昭堂","kana":"ほうこうじしょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.848475,"lng":137.61395278,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 270","desc":"開山堂北面に接続する開祖をまつる堂宇。桁行2間梁間2間、宝形造銅板葺で、正面中央に出入口を設ける。内部は格天井の一室で、奧に仏壇を設ける。尾垂木付二手先詰組に中備間斗束を加え、虹梁や肘木に丁寧な絵様を彫るなど、上質な意匠をもつ祠堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012920"},{"id":"00012913","register_sub_id":"101","register_pk":"368095","name":"方広寺鐘楼","kana":"ほうこうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84821111,"lng":137.61514167,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積15㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 263","desc":"本堂の正面東寄りに建つ。方一間袴腰付の形式で、入母屋造桟瓦葺である。上層は吹放しで四周に廻した縁を二手先腰組で支持し、格天井を張る。組物は二手先、中備は間斗束として、二軒繁垂木の軒を受ける。玉石積基壇上にあって、本堂前広場で存在感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012913"},{"id":"00012917","register_sub_id":"101","register_pk":"368099","name":"方広寺禅堂","kana":"ほうこうじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84911667,"lng":137.61568889,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 267","desc":"行在所東方の崖下に南面して建つ。入母屋造桟瓦葺妻入、正背面中央の出入口を両折桟唐戸とし、正面両脇に花頭窓を設ける。内部は土間四半敷の一室で、棟通りに達磨像を安置し、両側に畳敷の高床を設け、竿縁天井を張る。臨済宗寺院の構成要素となる附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012917"},{"id":"00012930","register_sub_id":"101","register_pk":"368112","name":"方広寺総門","kana":"ほうこうじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84809722,"lng":137.61840833,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口4.4m、左右袖塀付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 280","desc":"山門南方の参道入口に南面して建つ。切妻造桟瓦葺の一間高麗門で、扉は備えず、左右に矩折れの袖塀を付す。親柱は木鼻付の楣貫で固め、棟木との間に格子を入れ、二段の挿肘木で軒桁を受ける。良材を用いた丁寧なつくりで、門前景観を格調高く演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012930"},{"id":"00012912","register_sub_id":"101","register_pk":"368094","name":"方広寺大庫裡","kana":"ほうこうじだいくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84840833,"lng":137.61522222,"geo_status":"db","era":"大正前期／平成2年頃改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積513㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 262","desc":"南北棟の切妻造桟瓦葺の長大な庫裡で、本堂の東側に西面して建つ。正面中央の唐破風玄関の左右に入母屋の突出部を付した特徴的な表構えをもつ。北は展示室などの公的空間、南は事務室などの業務空間とする。豪壮な外観で、大本山にふさわしい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012912"},{"id":"00012910","register_sub_id":"101","register_pk":"368092","name":"方広寺勅使玄関","kana":"ほうこうじちょくしげんかん","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84826944,"lng":137.614725,"geo_status":"db","era":"大正4年／平成22年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡、左右築地塀付","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 260","desc":"本堂の西面南端に接続する賓客用玄関。間口1間奥行2間、向唐破風本瓦葺の屋根をかけ、左右に築地塀を付す。正面に桟唐戸を構え、床は四半敷、天井は木舞打茨垂木の現しとする。虹梁大瓶束の妻飾、菊花紋付の虹梁上蟇股など、本堂の表構えを格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012910"},{"id":"00012921","register_sub_id":"101","register_pk":"368103","name":"方広寺勅使門","kana":"ほうこうじちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84820556,"lng":137.61442222,"geo_status":"db","era":"明治40年／昭和10年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、間口4.1m、左右築地塀付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 271","desc":"凹形に後退した開山堂正面の石垣上に南面して建つ四脚門で、左右前方に築地塀を延ばす。切妻造銅板葺で、前後に軒唐破風を付す。扉は桟唐戸、組物は平三斗、妻飾は虹梁大瓶束笈形付で、冠木上の蟇股には菊花紋をあしらう。開山堂の表構えを重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012921"},{"id":"00012923","register_sub_id":"101","register_pk":"368105","name":"方広寺半僧坊真殿","kana":"ほうこうじはんそうぼうしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84852222,"lng":137.61388889,"geo_status":"db","era":"明治21年","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 273","desc":"拝殿北面に接続する半僧坊をまつる堂宇。桁行3間梁間3間、入母屋造桟瓦葺、側背面に縁を廻し、二軒繁垂木とする。内部は格天井の一室で、奧に仏壇を設ける。組物は出組、中備は蟇股、妻飾は虹梁大瓶束。建ちの低い構成と軒の深い緩やかな屋根に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012923"},{"id":"00012922","register_sub_id":"101","register_pk":"368104","name":"方広寺半僧坊拝殿","kana":"ほうこうじはんそうぼうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84846111,"lng":137.613975,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺及び瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 272","desc":"中心部の北西方に南面して建つ。桁行三間梁間五間、向拝一間で、背面中央に祈祷所を出して真殿に接続する。入母屋造銅板葺の正面千鳥破風付、向拝軒唐破風付。尾垂木付二手先の組物や虹梁大瓶束の妻飾、龍丸彫の海老虹梁など、外観を華やかな意匠で整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012922"},{"id":"00012924","register_sub_id":"101","register_pk":"368106","name":"方広寺札場","kana":"ほうこうじふだば","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84831111,"lng":137.61383333,"geo_status":"db","era":"明治21年頃／昭和49年頃改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積45㎡、渡廊下付","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 274","desc":"半僧坊拝殿の西側に東面して建つ。入母屋造銅板葺の平屋建で、北面を矩折れの渡廊下で拝殿に接続する。組物や妻飾はなく簡素だが、軒は二軒隅扇垂木で丁寧につくる。内部は3室を並べる。権現造風の真殿・拝殿とともに境内北西部の森厳な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012924"},{"id":"00012909","register_sub_id":"101","register_pk":"368091","name":"方広寺本堂","kana":"ほうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84845833,"lng":137.61485833,"geo_status":"db","era":"大正4年／平成22年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積735㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 259","desc":"浜松市街北西方にある臨済宗寺院。本堂は境内中心部に南面して建つ整形六間取の方丈形式で、正面に広縁を通し、側背面に廊下を廻す。懸造状に張出した正面の刎高欄付の切目縁や入母屋造桟瓦葺の大屋根、三重虹梁大瓶束の妻飾など、大本山の威容を存分に示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012909"},{"id":"00012926","register_sub_id":"101","register_pk":"368108","name":"方広寺水屋","kana":"ほうこうじみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84798611,"lng":137.61433333,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 276","desc":"神楽堂の東側に並んで建つ。切妻造桟瓦葺の起り屋根、吹放しの長方形平面で、鏡天井を張り、中央に手水石を据える。内転びの角柱を内法虹梁と頭貫で固め、台輪を廻す。組物は平三斗、一軒疎垂木とする。丁寧なつくりで、半僧坊前の景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012926"},{"id":"00008287","register_sub_id":"101","register_pk":"133929","name":"安久美神戸神明社神楽殿","kana":"あくみかんべしんめいしゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76799185,"lng":137.39454176,"geo_status":"db","era":"明治18年／昭和5年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0324","desc":"拝殿南西側に妻を東面して建て、桁行６．４ｍ梁間４．５ｍ、入母屋造及び切妻造桟瓦葺である。拝殿側の東・北面を開放できる構成とし、舞台に舟底天井を張り、アト座北面に切戸口、南面に社務所への出入口を開け、鏡板に松を描くなど、能舞台の諸要素を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008287"},{"id":"00008288","register_sub_id":"101","register_pk":"133930","name":"安久美神戸神明社神庫","kana":"あくみかんべしんめいしゃしんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76793236,"lng":137.39482254,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積30㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0325","desc":"拝殿南東側に神楽殿と対向して建つ。 桁行５．５ｍ梁間４．５ｍ、鉄筋コンクリート造平屋建、正面向拝付、寄棟造桟瓦葺である。外観は土蔵風として軒反りや隅木を作り、内部も柱型や隅木などを表す。伝統形式の土蔵を鉄筋コンクリート造で表現した神庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008288"},{"id":"00008289","register_sub_id":"101","register_pk":"133931","name":"安久美神戸神明社手水舎","kana":"あくみかんべしんめいしゃてみずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76775628,"lng":137.39470118,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、銅板葺、建築面積10㎡","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0326","desc":"拝殿前方の鳥居脇に建ち、桁行３．５ｍ梁間２．９ｍ、木造平屋建、切妻造、茅葺型銅板葺である。円柱を四方転びに建て、豕扠首組で棟木を受ける。素木の直材を基本とし、神明造を基調とした本殿などと調和した外観をもち、統一感のある境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008289"},{"id":"00008286","register_sub_id":"101","register_pk":"133928","name":"安久美神戸神明社幣殿及び拝殿","kana":"あくみかんべしんめいしゃへいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76811796,"lng":137.39470594,"geo_status":"db","era":"昭和5年／昭和45年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0323","desc":"本殿の前面に位置し、 桁行１８ｍ梁間４．８ｍの拝殿後方に、５．５ｍ四方の幣殿を張り出す。屋根は切妻造銅板葺で、棟上に千木と堅魚木をあげ、拝殿両端の神饌置場と楽舎を落棟とする。本殿と同じく、角南隆の設計による大型拝殿で、風格ある外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008286"},{"id":"00008285","register_sub_id":"101","register_pk":"133927","name":"安久美神戸神明社本殿","kana":"あくみかんべしんめいしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76825597,"lng":137.39473212,"geo_status":"db","era":"昭和5年／昭和45年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0322","desc":"境内北端に鎮座し、桁行三間梁間二間、神明造銅板葺で、周囲に縁をめぐらして木階を設け、棟に千木と堅魚木をあげる。直線的な部材構成や両妻に立つ棟持柱など神明造の制式に則ったつくりで、要所を錺金具で飾る。内務省神社局の角南隆による神社建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008285"},{"id":"00014159","register_sub_id":"101","register_pk":"508789","name":"朝日神社透塀（蕃塀）","kana":"あさひじんじゃばんぺい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区錦三丁目2219-1","lat":35.16883611,"lng":136.90392778,"geo_status":"db","era":"文化6年(1809)／昭和33年移築","year":1809,"year_source":"db","year_min":1809,"year_max":1809,"year_label":null,"structure":"木造、銅板葺、延長4.5m","structure_material":"木造","registered":"2022.02.17(令和4.02.17)","register_no":"23-0564","desc":"市街地に所在する旧城下の神社透垣で、大鳥居の西隣に位置する。切妻造銅板葺で疎垂木とし腕木に繰形を施す。規模は延長三間で円柱に長押付、各間連子窓に腰板壁とし、石製の控え柱で支える。尾張地方に多い形式の神前目隠し塀で、地域の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014159"},{"id":"00011966","register_sub_id":"101","register_pk":"211104","name":"安長寺山門","kana":"あんちょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市梅坪町五丁目14-1","lat":35.100129,"lng":137.15752,"geo_status":"db","era":"天保3年（1832）","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"23-505","desc":"豊田市西部の高台にあり東面する。一間一戸の楼門で、上層に三尊仏を安置していた。屋根は入母屋造で妻飾は虹梁大瓶束で渦状の笈形を付す。下層は柱を内転びに立て、絵様肘木と持送りで縁葛を支え、上層の組物は二手先で板支輪を地紋彫とし、大工の技量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011966"},{"id":"00014850","register_sub_id":"101","register_pk":"519110","name":"牛田八幡社覆殿","kana":"うしだはちまんしゃおおいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00089722,"lng":137.06878333,"geo_status":"db","era":"安政3年(1856)頃","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0604","desc":"内部に本殿を安置する桁行三間梁間二間、入母屋造桟瓦葺、正面一間向拝付の覆屋。正側面に擬宝珠高欄付の縁を廻らし、脇障子を建てる。身舎組物は出組で妻飾は虹梁大瓶束。向拝の虹梁形頭貫廻りや手挟などを彫刻で飾る。本格的な本殿形式の構成になる覆殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014850"},{"id":"00014851","register_sub_id":"101","register_pk":"519111","name":"牛田八幡社中殿及び袖廊","kana":"うしだはちまんしゃちゅうでんおよびそでろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00081667,"lng":137.06879167,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0605","desc":"覆殿の南面に位置する。入母屋造妻入、桟瓦葺とした中殿の両側面前寄りに、棟を直交して切妻造桟瓦葺の袖廊を付したＴ字平面で、西袖廊を神饌所、東を神具庫とする。中殿は土間で格天井を張り、正面の虹梁廻りや妻飾に、龍や虎、鶴の彫刻を密度高く配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014851"},{"id":"00014852","register_sub_id":"101","register_pk":"519112","name":"牛田八幡社拝殿","kana":"うしだはちまんしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00068889,"lng":137.06881389,"geo_status":"db","era":"明治15年","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0606","desc":"中心社殿の南端に位置する拝殿。南面して建つ桁行三間梁間三間、入母屋造桟瓦葺。組物は拳鼻付の出組として支輪を彫刻で満たす。二軒繁垂木、妻飾は虹梁大瓶束。内部は一室の拭板敷とし小組格天井を張る。南面の虹梁上や組物間など彫刻で華やかに飾った拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014852"},{"id":"00014849","register_sub_id":"101","register_pk":"519109","name":"牛田八幡社本殿","kana":"うしだはちまんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00090278,"lng":137.06878333,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積1.7㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0603","desc":"猿渡川北岸に位置する神社本殿。境内北の覆殿内に南面して建つ一間社流造こけら葺。正側面に擬宝珠高欄付縁を廻らし脇障子を建てる。身舎組物は出三斗、庇は三斗で中備は蟇股、妻飾は虹梁大瓶束。軸部や組物に塗装や彩色を残し、小社ながら整った意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014849"},{"id":"00005187","register_sub_id":"101","register_pk":"106177","name":"雲興寺鐘楼","kana":"うんこうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県瀬戸市白坂町131","lat":35.22233528,"lng":137.14492252,"geo_status":"db","era":"文化7","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造、瓦葺、建築面積28㎡","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0209","desc":"境内中心部，本堂南にある。桁行２間，梁間２間の袴腰付鐘楼で，入母屋造，桟瓦葺である。出組で縁を支え，軸部は円柱を立て，柱頭の外部に長押を廻し，二手先組物に中備を蟇股とする。棟札から年代等が明確で，地域における江戸後期の基準作のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005187"},{"id":"00013121","register_sub_id":"101","register_pk":"368278","name":"永住寺開山堂及び位牌堂","kana":"えいじゅうじかいさんどうおよびいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.902575,"lng":137.49830556,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0537","desc":"本堂北背後に続く切妻造の南北棟に開山堂と位牌堂を収める。前方の開山堂は奥行２間で前面円柱間に虹梁形鴨居を渡し、仏壇前には３連の虹梁を架ける。仏壇は中央間に花頭口を設けて仏龕を張出す。続く位牌堂は奥行７間で、東西両側に位牌壇を設け高窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013121"},{"id":"00013125","register_sub_id":"101","register_pk":"368282","name":"永住寺経蔵","kana":"えいじゅうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90271111,"lng":137.49858056,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0541","desc":"境内の北東、書院北方に南面して建つ、方１０尺規模の土蔵造である。屋根は宝形造とし、軒は一軒疎垂木とする。外壁は漆喰塗である。正面に木階２級を設け、戸口は土塗戸を引分ける。内部は板敷、棹縁天井で北奥に壇を設ける。伽藍を構成する小建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013125"},{"id":"00013122","register_sub_id":"101","register_pk":"368279","name":"永住寺庫裡及び書院","kana":"えいじゅうじくりおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90235556,"lng":137.49862222,"geo_status":"db","era":"文化7年（1810）","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積702㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0538","desc":"本堂東に書院が接続し、中庭や廊下などを介して南の庫裡へ続く。庫裡南の土間に竈を置き、北西に広い板敷を設ける。西の土間通路は矩折れに書院南の玄関に至る。書院は北に１５畳２室を並べ、東室に床棚を設ける。曹洞宗伽藍を特徴づける大規模な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013122"},{"id":"00014487","register_sub_id":"101","register_pk":"513901","name":"永住寺山門","kana":"えいじゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90178889,"lng":137.49858611,"geo_status":"db","era":"寛政6年（1794）","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"23 - 0586","desc":"曹洞宗寺院の伽藍南に開く表門。切妻造本瓦葺の四脚門、二軒繁垂木、柱は円柱で礎盤に立て、控柱間に虹梁を架け、棟持柱の主柱と貫で繋ぐ。大工は信州立川流、妻面の挿肘木の斗組は特徴的で、虹梁廻りを立体的な彫刻で飾る。総じて重厚で華やかな総欅造の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014487"},{"id":"00013124","register_sub_id":"101","register_pk":"368281","name":"永住寺衆寮","kana":"えいじゅうじしゅりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90218333,"lng":137.49828889,"geo_status":"db","era":"享保7年（1722）","year":1722,"year_source":"db","year_min":1722,"year_max":1722,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0540","desc":"本堂の南西に東面して建つ、切妻造の南北棟である。南の禅堂との間に一段低く屋根を架ける。内部は東に土間を通し、床上部は２列６室で東列が南から８畳と６畳２室、西列が６畳と４・５畳２室である。禅宗伽藍を構成する特徴的な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013124"},{"id":"00013123","register_sub_id":"101","register_pk":"368280","name":"永住寺禅堂","kana":"えいじゅうじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90228611,"lng":137.49825278,"geo_status":"db","era":"享保7年（1722）","year":1722,"year_source":"db","year_min":1722,"year_max":1722,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0539","desc":"本堂南西に東面して建つ切妻造の南北棟で、正面に切妻向拝を付す。内部は前面に土間を通し南北を引違戸とする。床上は両脇間と奥の１間幅を板敷、中央を畳敷とする。西背面の張出しを仏壇とする。中央の畳敷は元土間であった。禅宗伽藍の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013123"},{"id":"00014486","register_sub_id":"101","register_pk":"513900","name":"永住寺鎮守殿","kana":"えいじゅうじちんじゅでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90210833,"lng":137.49830556,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"23 - 0585","desc":"曹洞宗寺院の伽藍南西端、稲荷信仰と習合する吒枳尼天を祀る小堂。入母屋造妻入、二軒半繁垂木で正面に向拝を付し、内部は内・外陣を虹梁で分け、共に格天井とする。内々陣壇上に一間社流造宮殿を置く。豊川稲荷に近い土地柄を示し、歴史的伽藍を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014486"},{"id":"00013120","register_sub_id":"101","register_pk":"368277","name":"永住寺本堂","kana":"えいじゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90241667,"lng":137.498375,"geo_status":"db","era":"元禄10年（1697）／享保2年（1717）改修","year":1697,"year_source":"db","year_min":1697,"year_max":1697,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積298㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0536","desc":"境内中央に南面して建つ、入母屋造桟瓦葺の本堂。２列６室平面で、後列中央を内陣とする。前面に畳敷広縁を通し、東面と西面を畳縁とする。内陣前の２柱と来迎柱は円柱で他は角柱である。広縁は元は縁と土間で書院に通じており、曹洞宗本堂の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013120"},{"id":"00009299","register_sub_id":"101","register_pk":"194092","name":"圓明寺庫裏","kana":"えんめいじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38211626,"lng":136.94177009,"geo_status":"db","era":"江戸末期／明治中期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積314㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0353","desc":"本堂南西側に東面して建つ。木造平屋一部二階建、建築面積三一四平方メートル、切妻造桟瓦葺で正面を下屋とする。内部は入口付近を土間とし北側に座敷を並べる。城下の町家を移築したもので、起り屋根や、上下階の正面各間に建てた格子などに名残をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009299"},{"id":"00009301","register_sub_id":"101","register_pk":"194094","name":"圓明寺山門","kana":"えんめいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38199919,"lng":136.94194998,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、銅板葺、間口2.5m","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0355","desc":"境内の南正面に構える四脚門形式の山門。桁行二・五メートル梁間二・一メートル、切妻造銅板葺で正面に軒唐破風を付ける。本柱は円柱、控柱を几帳面取角柱とし、正面は虹梁と蟇股を二段重ねて華やかなつくりとする。伊藤平左衛門による材工ともに良質な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009301"},{"id":"00009300","register_sub_id":"101","register_pk":"194093","name":"圓明寺鐘楼","kana":"えんめいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38205772,"lng":136.94203849,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積9㎡","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0354","desc":"境内東側、庫裏と向き合って基壇上に建つ、入母屋造本瓦葺の吹放し鐘楼。三メートル四方の平面で、軸部は禅宗様を基調とし、組物は二手先詰組、妻飾は虹梁大瓶束とする。深い軒には強い軒反りをもたせるなど本格的なつくりで、境内景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009300"},{"id":"00009298","register_sub_id":"101","register_pk":"194091","name":"圓明寺僧寮","kana":"えんめいじそうりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38220192,"lng":136.94187288,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0352","desc":"本堂と庫裏の間に建ち、木造平屋建、建築面積九〇平方メートル、切妻造桟瓦葺で、本堂側の東面に切妻造の式台玄関を構える。東側に一間幅の廊下を通し、西側には北から四畳半など四室を配する。玄関廻りに良材を用いた、丁寧なつくりになる接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009298"},{"id":"00009297","register_sub_id":"101","register_pk":"194090","name":"圓明寺本堂","kana":"えんめいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38230899,"lng":136.94196996,"geo_status":"db","era":"江戸前期／元禄2年改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0351","desc":"境内北奥に建ち、桁行一五・三メートル梁間一六・七メートル、入母屋造本瓦葺で、一間向拝を付ける。堂内は後門形式の内陣と余間、外陣を配し、外陣後寄りに矢来内を画し、前面を広縁とする。全て角柱とする点や細部に古式をとどめる浄土真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009297"},{"id":"00014835","register_sub_id":"101","register_pk":"519095","name":"大目神社本殿","kana":"おおまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県瀬戸市巡間町1","lat":35.22003889,"lng":137.13156111,"geo_status":"db","era":"文化2年(1805)／昭和52年改修","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0589","desc":"赤津の大目森の丘に位置する神社本殿。南面する三間社流造銅板葺で、三方に擬宝珠高欄付の縁を廻らし、木階と浜床を付す。組物は平三斗、軒は二軒繁垂木、妻飾は豕扠首。正面柱間は吹放ち、柱筋から北に寄せて幣軸構えとする形式で、当地域の特徴を示す本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014835"},{"id":"00002772","register_sub_id":"101","register_pk":"103762","name":"花岳寺本堂","kana":"かがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県西尾市吉良町岡山山王山67","lat":34.84333,"lng":137.082275,"geo_status":"db","era":"貞享1","year":1684,"year_source":"db","year_min":1684,"year_max":1684,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"23 － 0059","desc":"吉良氏の菩提寺となった臨済宗寺院本堂。入母屋造，桟瓦葺で，六間取りの典型的な形式をとるが，仏壇の構えや木割が細い点に古式を伝える。建具等一部に改造はあるが主要材はほとんど当初材が残り，１７世紀後期における地域の禅宗本堂を知る上で重要な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002772"},{"id":"00004775","register_sub_id":"101","register_pk":"105765","name":"覚王寺庫裏","kana":"かくおうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.353275,"lng":136.922256,"geo_status":"db","era":"天保11","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積400㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0201","desc":"南北棟で煙出付の切妻造，妻入，桟瓦葺で，本堂とは西面の廊下で繋がる。平面は南側を土間とし，床上部は棟通りで東西に分かれ，北西部に１５畳大で床・棚付の座敷を設ける。桁行２４ｍに及ぶ雄大な規模で，禅宗寺院庫裏らしく，南妻面は海老虹梁などで飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004775"},{"id":"00004778","register_sub_id":"101","register_pk":"105768","name":"覚王寺山門","kana":"かくおうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.35293265,"lng":136.92191531,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口3.2m、潜門及び左右袖塀付","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0204","desc":"１間１戸薬医門で，左右に潜門と塀を附属し，段違いの屋根を連続する。軒は二軒繁垂木，切妻造，桟瓦葺の屋根で，組物は三斗，妻飾は虹梁・大瓶束とする。虹梁等の絵様は彫りが深いが華美ではなく，総欅になる丁寧なつくりで，正面入口に相応しい品格を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004778"},{"id":"00004777","register_sub_id":"101","register_pk":"105767","name":"覚王寺鐘楼","kana":"かくおうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.35319266,"lng":136.921753,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、建築面積29㎡","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0203","desc":"本堂南方にある。切石積基壇上に建ち，袴腰を簓子下見板張，擬宝珠高欄付の縁は出組詰組で受け，中備に蟇股を入れる。組物は出組詰組，蟇股・軒支輪を設ける。二軒繁垂木，入母屋造，桟瓦葺で，板天井には天女を描く。手の込んだつくりの方１間の袴腰付鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004777"},{"id":"00004776","register_sub_id":"101","register_pk":"105766","name":"覚王寺大日堂","kana":"かくおうじだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.35327262,"lng":136.92178307,"geo_status":"db","era":"寛政6","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0202","desc":"本堂の南西にあり，東を正面とする。８畳大の１室の背面に仏壇を張り出した平面で，１間向拝を設け，正面と両側面に切目縁をつける。屋根は宝形造，桟瓦葺で，仏壇廻りでは丸柱で組物を用いる。簡素なつくりの小堂であるが，近世の境内構成を伝える上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004776"},{"id":"00004774","register_sub_id":"101","register_pk":"105764","name":"覚王寺本堂","kana":"かくおうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.353355,"lng":136.922012,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積354㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0200","desc":"ほぼ南面して建つ入母屋造，桟瓦葺，方丈形式の本堂。正面に広縁を設けた６間取平面で，室中と上間・下間は境を竹の節欄間として格天井を連続させ，上奥間の２室構成やつし２階は独特である。装飾は控えているが，たちの高い外観は江戸後期の造形とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004774"},{"id":"00008698","register_sub_id":"101","register_pk":"149419","name":"カトリック主税町教会司祭館","kana":"かとりっくちからまちきょうかいしさいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区主税町3-33","lat":35.18047258,"lng":136.91429225,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階地下1階建、瓦葺、建築面積126㎡","structure_material":"木造2階地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0335","desc":"信者会館の東に接して建つ。木造2階地下1階建、建築面積126㎡。寄棟造桟瓦葺、逆Ｌ字形屋根で、東面に小屋根を突き出す。北面西寄りに庇をかけ、玄関とする。外壁は下見板張、ペンキ塗。東面に1、2階通しのベイウインドゥを設け、外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008698"},{"id":"00008697","register_sub_id":"101","register_pk":"149418","name":"カトリック主税町教会信者会館","kana":"かとりっくちからまちきょうかいしんじゃかいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区主税町3-33","lat":35.18054933,"lng":136.91419866,"geo_status":"db","era":"明治中期／昭和55年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0334","desc":"主税町の角地に敷地を占める。北面する木造2階建、桁行11ｍ梁間8.2ｍ。寄棟造桟瓦葺、中央に切妻造玄関を構える。中廊下式平面になり、南面にベランダを設ける。外壁は下見板張で、白いペンキが塗られる。コロニアルスタイルを基本とする明治期洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008697"},{"id":"00008699","register_sub_id":"101","register_pk":"149420","name":"カトリック主税町教会煉瓦塀","kana":"かとりっくちからまちきょうかいれんがべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区主税町3-33","lat":35.18096113,"lng":136.91447756,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造、延長29m","structure_material":"煉瓦造","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0336","desc":"敷地北側、主税町筋沿い建つ。煉瓦造で、延長29ｍ、高さ2.1ｍ、厚さ35㎝。切石を2段積み、その上にイギリス積とし、上部は笠石状に張り出す。敷地内側には3.7ｍ間隔で、幅22㎝、出12㎝の控柱を付ける。主税町の伝統的な町並みを構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008699"},{"id":"00003649","register_sub_id":"101","register_pk":"104639","name":"興禅寺庫裏","kana":"こうぜんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市羽黒城屋敷16","lat":35.35315882,"lng":136.94923375,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積312㎡","structure_material":"木造平屋一部2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0062","desc":"木造一部２階建，切妻造，本瓦葺。本堂東に位置する南北棟で，西側の接客部と東側の居住部に二分し，各々表から土間，板間，座敷で構成する。居住部の土間と板間は洋室に改装された。妻に表した小屋組の虹梁，太瓶束，海老虹梁や煙出しの越屋根が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003649"},{"id":"00005620","register_sub_id":"101","register_pk":"106608","name":"興禅寺山門","kana":"こうぜんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字羽黒字城屋敷16","lat":35.35273138,"lng":136.94901341,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、間口3.6m、左右袖塀付","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"23 － 0224","desc":"切妻造，本瓦葺の四脚門で，本堂前方に南面して建ち，左右にＬ字型の築地塀を延ばす。軸部は親柱を円，控柱を角とし，三斗を組む。妻飾は虹梁大瓶束笈形，軒は二軒繁垂木とする。化粧材は総欅で，木目が美しい鏡天井，精緻で流麗な装飾細部等，造形的にも優作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005620"},{"id":"00005619","register_sub_id":"101","register_pk":"106607","name":"興禅寺本堂","kana":"こうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字羽黒字城屋敷16","lat":35.353165,"lng":136.948929,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積332㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"23 － 0223","desc":"南面して建つ。六間取平面で，南・東・西の各面に入側を廻し，四周切目縁付で，背面に後堂を出す。出組，二軒で寄棟造の屋根を架け，四周に舟肘木，二軒の下屋を廻す。方丈形式の本堂では珍しい二重屋根の堂々たる外観を構成し，地域の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005619"},{"id":"00010168","register_sub_id":"101","register_pk":"198001","name":"財賀寺三十三観音堂","kana":"ざいがじさんじゅうさんかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山3","lat":34.874317,"lng":137.356939,"geo_status":"db","era":"寛政12","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0416","desc":"本堂の南東に西面して建つ。桁行三間梁間二間の切妻造平入で、正面中央間は実長二間と広くとって差鴨居を入れる。堂内は間仕切のない一室で、中央に框を入れて奥一間に仏壇を造作し、三十三観音を祀る。江戸後期に当地で流行した観音霊場巡礼を反映する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010168"},{"id":"00010167","register_sub_id":"101","register_pk":"198000","name":"財賀寺本堂","kana":"ざいがじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山3","lat":34.874762,"lng":137.356812,"geo_status":"db","era":"文政6／昭和3・昭和後期改修","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0415","desc":"山中の伽藍上段に建つ五間堂で、前側梁間二間を外陣、後半を内陣と両脇陣、後陣とする。外陣は、桁行の三間梁で天井を支持する、当地方に散見される架構をもつ。棟梁岡田五左衛門の特徴が架構以外の細部にも認められる。地方的特色を備え、規模も充実した本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010167"},{"id":"00010169","register_sub_id":"101","register_pk":"198002","name":"財賀寺文殊堂","kana":"ざいがじもんじゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山3","lat":34.873548,"lng":137.355654,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0417","desc":"伽藍中段に南面して建つ。入母屋造妻入で、正面に向拝を設ける。間口三間で、前一間を板敷の外陣、中三間を護摩壇を設ける内陣、背面に仏壇を張出して屋根を縋破風状とする。棟梁は岡田五左衛門で、蟇股などにその特徴が見られる。地域信仰の様相を伝える堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010169"},{"id":"00014162","register_sub_id":"101","register_pk":"508792","name":"西心寺山門","kana":"さいしんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市川島町西屋敷16","lat":34.92736667,"lng":137.10609722,"geo_status":"db","era":"明治36年","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造、瓦葺、間口3.6m、左右袖塀付","structure_material":"木造","registered":"2022.02.17(令和4.02.17)","register_no":"23-0567","desc":"安城市東端の真宗寺院本堂の東正面に建つ四脚門。切妻造桟瓦葺、両脇に袖塀を設ける。主柱は円柱、控柱は几帳面取角柱、いずれも礎石、礎盤上に立つ。主柱に冠木を架け、虹梁で控柱と繋ぎ、三斗組。冠木を地紋彫とし、龍をはじめ随所に彫刻を飾る華麗な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014162"},{"id":"00014161","register_sub_id":"101","register_pk":"508791","name":"西心寺本堂","kana":"さいしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県安城市川島町西屋敷16","lat":34.92748333,"lng":137.10579722,"geo_status":"db","era":"天保6年(1835)","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0566","desc":"安城市東端に位置。桁行９間梁間７間、入母屋造桟瓦葺で向拝を付す。妻に鰭を波型とする懸魚を付す。内部は表側を外陣、中央を矢来内、奥を内陣及び余間とする真宗寺院本堂の典型。中規模だが用材を吟味し、特徴的な彫刻等、地域の岡田大工の遺構として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014161"},{"id":"00006609","register_sub_id":"101","register_pk":"107592","name":"西蓮寺蔵","kana":"さいれんじくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38212455,"lng":136.942551,"geo_status":"db","era":"明治期／昭和12移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0276","desc":"庫裏の東南に西面して建つ。桁行３．６ｍ梁間３．３ｍの規模で、切妻造妻入桟瓦葺とする。正面は漆喰塗とし、１階には庇を設け、北寄りに両開土戸を構え、２階には窓を穿ち、持送り付の庇を付ける。内部は１、２階とも１室の板敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006609"},{"id":"00006607","register_sub_id":"101","register_pk":"107590","name":"西蓮寺庫裏","kana":"さいれんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38220265,"lng":136.942413,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積143㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0274","desc":"本堂の東、南面して建つ。桁行６間半梁間６間の規模で、切妻造平入桟瓦葺とする。東端を土間とし、西側に座敷４室を田字型に配し、南に１間幅の畳縁、北に板敷を設ける。細い木柄を組み上げ和小屋を造る。住宅風の外観になる庫裏である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006607"},{"id":"00006608","register_sub_id":"101","register_pk":"107591","name":"西蓮寺山門","kana":"さいれんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38200537,"lng":136.9421971,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.1m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0277","desc":"本堂の正面、通りに南面して建つ。切妻造桟瓦葺の１間薬医門で、両側に潜戸を設ける。男梁上に三斗組、中備に蟇股を置き、その上に虹梁大瓶束で妻を造る。二軒疎垂木。木鼻を透かし彫りにするなど時代が下がるが、扉の八双金具等は古風である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006608"},{"id":"00006737","register_sub_id":"101","register_pk":"107720","name":"西蓮寺書院","kana":"さいれんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.3822041,"lng":136.94234629,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0275","desc":"本堂と庫裏の間に南面して建つ。桁行４間梁間６間規模の２階建で、切妻造平入桟瓦葺とし、正面西寄りに入母屋造屋根を突き出し、式台とする。室内はトコと違棚をもつ主室と次の間を南北に並べる。一部に前身建物材を再用。繊細な意匠になる書院建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006737"},{"id":"00006606","register_sub_id":"101","register_pk":"107589","name":"西蓮寺本堂","kana":"さいれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38220774,"lng":136.94222619,"geo_status":"db","era":"宝暦10／平成8改修","year":1760,"year_source":"db","year_min":1760,"year_max":1760,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0273","desc":"寺内町のほぼ中央、通りに南面する寺地の中央に南面して建つ。入母屋造本瓦葺の５間堂で１間向拝を付ける。外陣内部を柱列で仕切らず、矢来内も設けず、内陣も当初は間口一杯の仏壇とする平面形式をもつ浄土真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006606"},{"id":"00004583","register_sub_id":"101","register_pk":"105573","name":"實成寺山門","kana":"じつじょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県あま市中萱津南宿254","lat":35.18679876,"lng":136.84334824,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0187","desc":"本堂の前方，やや北寄りに東面して建つ。四脚門，切妻造，本瓦葺で，礎盤上に親柱，控柱とも丸柱を立て，頭貫と妻虹梁で固め，軒は二軒疎垂木で，木舞打ちとする。丸柱は粽付で，親柱を上部に延ばした禅宗様の大型の山門で，寺観正面の構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004583"},{"id":"00004582","register_sub_id":"101","register_pk":"105572","name":"實成寺本堂","kana":"じつじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県あま市中萱津南宿254","lat":35.18683442,"lng":136.84288642,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積246㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0186","desc":"桁行５間，梁間６間，宝形造，桟瓦葺で，正側面に１間幅の縁を廻し，正面に向拝１間を付す。内部は前方２間を外陣，後方中央間口３間，奥行４間を内陣，両脇を脇陣とし，内陣後方に来迎柱を後退し須弥壇を構える。平面や軸部構成に日蓮宗本堂の古式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004582"},{"id":"00003432","register_sub_id":"101","register_pk":"104422","name":"実相寺庫裡","kana":"じっそうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県西尾市上町下屋敷15","lat":34.87639452,"lng":137.03659987,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"23 － 0061","desc":"方丈東方に玄関部を介して接続する。桁行１４．７ｍ，梁間１５．４ｍ，入母屋造妻入，桟瓦葺（もと茅葺）で，南東隅に部屋を張り出す。前面土間とその奥の床上部は間仕切がなく，大梁を縦横に架け豪壮な大空間を造る。簡素だが禅宗伽藍構成上欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003432"},{"id":"00003431","register_sub_id":"101","register_pk":"104421","name":"実相寺方丈","kana":"じっそうじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県西尾市上町下屋敷15","lat":34.87642142,"lng":137.03631362,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積208㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"23 － 0060","desc":"吉良氏建立になる臨済宗寺院方丈で，室中を中心とした６間取平面の中心部を残す。改造により両側面広縁が撤去され，屋根も切妻造となるが，内法の低い内部など江戸初期の雰囲気をよく残す。木柄の太い大型の建物で，東方の庫裡とともに伽藍の中核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003431"},{"id":"00004773","register_sub_id":"101","register_pk":"105763","name":"寂光院山門","kana":"じゃっこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.39622183,"lng":136.96227365,"geo_status":"db","era":"天保7","year":1836,"year_source":"db","year_min":1836,"year_max":1836,"year_label":null,"structure":"木造、瓦葺、間口2.2m、袖塀付","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0199","desc":"境内入口に建つ。形式は１間１戸薬医門で，二軒繁垂木，屋根は切妻造，本瓦葺である。組物は三斗で，妻は詰組，背面は中備に龍の彫物を入れる。妻飾は大瓶束で，両側には牡丹を彫った笈形をつける。木太いつくりで，虹梁・木鼻の絵様に時代の特徴がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004773"},{"id":"00004771","register_sub_id":"101","register_pk":"105761","name":"寂光院随求堂","kana":"じゃっこういんずいぐどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.39537404,"lng":136.96345738,"geo_status":"db","era":"文化2","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0197","desc":"本堂西に東面して建ち，渡廊下で結ばれる。桁行５間，梁間３間，一軒，入母屋造，桟瓦葺で，４周に擬宝珠高欄付の切目縁を廻す。軸部は角柱で床下部を高くつくり，縁を絵様付持送り板で受ける。側廻りに蔀戸を多用した住宅風の外観は籠堂の性質を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004771"},{"id":"00004772","register_sub_id":"101","register_pk":"105762","name":"寂光院弁天堂","kana":"じゃっこういんべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.39561562,"lng":136.96372042,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0198","desc":"本堂北方の高所にある。ほぼ正六角形の平面をもつ小堂で，前半を吹放しで板床張の見世棚風とし，中央境に格子戸を設け，後方を板壁で囲った内陣とする。柱や屋根を六角形につくり，天井の棹や垂木は放射状に配る。弁天像台座裏の墨書銘と同時期と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004772"},{"id":"00004770","register_sub_id":"101","register_pk":"105760","name":"寂光院本堂","kana":"じゃっこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.395348,"lng":136.963638,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡、渡廊付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0196","desc":"桁行５間，梁間５間，寄棟造，正面１間向拝付，桟瓦葺で，４周に切目縁を廻す。前２間分を吹放しで小組格天井の外陣とし，後方の内陣には禅宗様須弥壇を構え，厨子を置く。軸部は円柱で，組物は出組とする。装飾を押さえた伝統的形式になる本格的な本堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004770"},{"id":"00004767","register_sub_id":"101","register_pk":"105757","name":"春江院庫裏","kana":"しゅんこういんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06213869,"lng":136.93414308,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積387㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0193","desc":"書院の北にある。南北棟の切妻造，桟瓦葺，２階建で，北面に下屋を降ろし，東面北寄に玄関を配する。北東隅の吹抜土間は豪放な梁組を現すが，１階・２階とも中廊下式とした近代的な平面構成で，洋風意匠の階段手摺子など，伝統の中に近代的要素が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004767"},{"id":"00004768","register_sub_id":"101","register_pk":"105758","name":"春江院山門","kana":"しゅんこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06272272,"lng":136.93446466,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0194","desc":"境内の北入口に北面して建つ。正面の控柱は後世の補強材で，形式は１間１戸薬医門で，二軒疎垂木，屋根は切妻造，本瓦葺である。組物は三斗と簡素であるが，妻飾には大柄の板蟇股を用い，意匠の要にする。虹梁・木鼻・蟇股の絵様には時代の特徴が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004768"},{"id":"00004769","register_sub_id":"101","register_pk":"105759","name":"春江院鐘楼","kana":"しゅんこういんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06221724,"lng":136.93432045,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造、瓦葺、建築面積22㎡","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0195","desc":"本堂北にある。玉石で築いた基壇上に建ち，袴腰は簓子下見板張，縁には擬宝珠高欄を廻す。組物は出三斗の詰組であるが，壁付を横広がりとし，二軒扇垂木，入母屋造，桟瓦葺で，格天井の格間には彩色を施す。禅宗様意匠になる均整のとれた方１間の袴腰付鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004769"},{"id":"00004766","register_sub_id":"101","register_pk":"105756","name":"春江院茶室","kana":"しゅんこういんちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06189779,"lng":136.93401552,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺一部檜皮葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0192","desc":"書院の西にあり，尾州久田流茶道の開祖である下村實栗の作になる草庵風茶室。床を入れて４畳ほどと小規模だが，杉皮葺屋根は格子状に組んだ竹で押さえ，格子だけでなく，棹縁天井の棹や化粧屋根裏の垂木や木舞を竹とするなど，竹を多用した独特の構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004766"},{"id":"00004765","register_sub_id":"101","register_pk":"105755","name":"春江院不老閣","kana":"しゅんこういんふろうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06180438,"lng":136.9340138,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0191","desc":"書院の南西方にある切妻造，下屋庇付の平屋建で，外観は簡素な建物。内部は南に床付８畳の一の間，北に４畳半の二の間を配し，南と西に縁を廻す。磨き丸太の床柱，床脇の網代天井，丸垂木に木舞打とした縁の化粧屋根裏など，数寄屋の趣向が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004765"},{"id":"00004764","register_sub_id":"101","register_pk":"105754","name":"春江院本玄関及び書院","kana":"しゅんこういんほんげんかんおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06190821,"lng":136.93423421,"geo_status":"db","era":"江戸後期／明治12移築増改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0190","desc":"書院は本堂の西に建つ平屋建で，その間を本玄関が繋ぐ。本玄関は廊下と和室からなり，北面中央に式台を設ける。書院は床・棚・付書院のある１２畳間と床付の１８畳間からなり，Ｌ字型に広縁がつき，建具や欄間が繊細で，襖絵や板絵などもよく残る瀟洒な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004764"},{"id":"00004763","register_sub_id":"101","register_pk":"105753","name":"春江院本堂","kana":"しゅんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.0618638,"lng":136.9343648,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積424㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0189","desc":"北を正面とする入母屋造，正面向拝付，本瓦葺の本堂。正面に広縁を設けた６間取平面で，北と東に切目縁を廻す。軸部は来迎柱を除いて角柱で，長押・貫で結ぶ。妻飾の虹梁・蟇股・懸魚などに江戸後期らしい装飾を施すが，簡明で端正な方丈形式のつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004763"},{"id":"00009303","register_sub_id":"101","register_pk":"194096","name":"祥雲寺弘法堂","kana":"しょううんじこうぼうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券5-1","lat":35.37901025,"lng":136.93839225,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0357","desc":"境内中央北寄りに南面する。桁行一四・二メートル梁間六メートル、入母屋造桟瓦葺で、正面に一間向拝を付ける。内部は東寄りに一〇畳三室を並べ落縁を廻らす。各室は格天井を張り、北奥に仏壇を備える。西端は物置とする。弘法大師を祀り大師堂ともよばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009303"},{"id":"00009304","register_sub_id":"101","register_pk":"194097","name":"祥雲寺鐘楼","kana":"しょううんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券5-1","lat":35.37884274,"lng":136.9383775,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0358","desc":"弘法堂と参道を挟んで向き合う。方一間、袴腰付、入母屋造桟瓦葺である。玉石積の基壇上に建ち、擬宝珠高欄付縁を廻らし、上層は円柱を頭貫・台輪で固め、組物三斗、中備蟇股とし格天井を張る。装飾を抑えた端正なつくりの鐘楼で穏やかな境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009304"},{"id":"00009302","register_sub_id":"101","register_pk":"194095","name":"祥雲寺本堂","kana":"しょううんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券5-1","lat":35.37876184,"lng":136.93804152,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0356","desc":"境内奥に東面し、桁行一五・一メートル梁間一四・二メートル、入母屋造桟瓦葺。内部は方丈型六間取形式で正面に広縁を配し、内陣は来迎柱を立てて須弥壇をおき小組格天井を張る。二軒疎垂木の軒廻りや柱上の舟肘木がやや復古的な形式で穏やかな印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009302"},{"id":"00005189","register_sub_id":"101","register_pk":"106179","name":"浄照寺庫裏","kana":"じょうしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市若林西町向屋敷62","lat":35.031528,"lng":137.099701,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0211","desc":"本堂東にある。長大な平入建物で，屋根は切妻造段違，桟瓦葺である。正面の南面東端を玄関，その奥の土間は豪放な梁組を見せ，床上部は３室を２列に配する。軸部は差物を多用した堅固な構法である。墨書から年代と棟梁が明確で，この地域の庫裏の指標となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005189"},{"id":"00005190","register_sub_id":"101","register_pk":"106180","name":"浄照寺書院","kana":"じょうしょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊田市若林西町向屋敷62","lat":35.03176731,"lng":137.09959472,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0212","desc":"本堂の北方にある。東西棟の切妻造で，四面に下屋を廻し，桟瓦葺とする。平面は８畳２室と６畳２室を田の字形とし，四周を縁で囲む。規模が小さく，下見板張の外観は素朴であるが，良材を吟味して用い，繊細な板欄間など瀟洒な数寄屋風のつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005190"},{"id":"00005188","register_sub_id":"101","register_pk":"106178","name":"浄照寺本堂","kana":"じょうしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊田市若林西町向屋敷62","lat":35.03155817,"lng":137.09936117,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積480㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0210","desc":"南東を向いて建つ。正側面ともに約２０ｍと規模が大きく，入母屋造，桟瓦葺，向拝付で，平面は吹放の縁，外陣，矢来と続き，内陣は本間とその両側の余間及び飛檐間からなり，後堂がつく。伝統的な形式を踏襲しつつ，絵様細部や彫物等に近代の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005188"},{"id":"00006610","register_sub_id":"101","register_pk":"107593","name":"浄誓寺本堂","kana":"じょうせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券256","lat":35.381672,"lng":136.941833,"geo_status":"db","era":"文化5／平成7改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積191㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0272","desc":"犬山城東南の寺内町に所在する。通りに北面する境内の中央に東面して建つ。入母屋造本瓦葺で、正面に１間向拝を設ける。堂内は外陣と矢来内、内陣からなり、内陣は後門形式となる。小組格天井を張り、龍などの豊かな彫刻が施される近世浄土真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006610"},{"id":"00006604","register_sub_id":"101","register_pk":"107587","name":"常満寺山門","kana":"じょうまんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券281","lat":35.38348552,"lng":136.937958,"geo_status":"db","era":"江戸末期／明治10移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0270","desc":"通りから西に入った位置に東面して建つ。犬山城松の丸裏門を移築した、切妻造桟瓦葺の１間薬医門。太い木柄で、組物はなく、軒は一軒疎垂木とする。装飾のない簡明な意匠ながら、豪放な気風を有しており、城門としての風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006604"},{"id":"00006605","register_sub_id":"101","register_pk":"107588","name":"常満寺鐘楼","kana":"じょうまんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券281","lat":35.38337552,"lng":136.9375191,"geo_status":"db","era":"寛政8","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0267","desc":"本堂の南方に東西棟で建つ。四周に縁を廻す方１間吹放ちの袴腰付鐘楼で、入母屋造桟瓦葺とする。方柱を頭貫と台輪で固め、三斗組とし、中備に蟇股を置く。軒は一軒疎垂木で、妻は木連格子とする。伸びやかな屋根勾配をもつ鐘楼で、境内景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006605"},{"id":"00012552","register_sub_id":"101","register_pk":"367847","name":"真宗大谷派名古屋別院東門及び土塀","kana":"しんしゅうおおたにはなごやべついんひがしもんおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区橘二丁目8-55","lat":35.151138,"lng":136.901276,"geo_status":"geocoded","era":"江戸後期／平成28年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"東門 木造、瓦葺、間口4.2m、左右袖塀及び北方潜戸付 土塀 土塀、瓦葺、総延長9.8m","structure_material":"東門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0523","desc":"市中心部にある境内東面に開く門と両脇に延びる土塀。切妻造本瓦葺の一間一戸高麗門で、本柱を木鼻付の楣で固め、3筋の腕木で軒桁を受ける。量感ある部材を用いて規模雄大につくり、大寺院の風格ある表構えを形成する。戦災を免れて市内に残る希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012552"},{"id":"00014026","register_sub_id":"101","register_pk":"508286","name":"瑞芳院本堂及び庫裡","kana":"ずいほういんほんどうおよびくり","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県一宮市中町一丁目4-1","lat":35.29513611,"lng":136.79879722,"geo_status":"db","era":"文化10年（1813）／大正4年移築","year":1813,"year_source":"db","year_min":1813,"year_max":1813,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"23 - 0563","desc":"濃尾地震被害からの復興に際し妙興寺から移築した方丈形式の本堂で、桁行北側に庫裏が連なる。切妻造桟瓦葺で妻飾りを木連格子と懸魚とし、四周に下屋を廻らす。内陣は小組格天井で正面に筬欄間を構えて須弥壇に花頭口を並べる。市街地に歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014026"},{"id":"00008127","register_sub_id":"101","register_pk":"132525","name":"瀬戸永泉教会礼拝堂","kana":"せとえいせんきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県瀬戸市杉塚町5","lat":35.22658164,"lng":137.10536807,"geo_status":"db","era":"明治33年／昭和5年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"23 － 0321","desc":"旧道南側の敷地に西面して建つ。桁行１１ｍ梁間７．４ｍの木造平屋建、切妻造桟瓦葺妻入とし、正面に玄関ポーチを付設。外装下見板張で、半円に近い尖塔アーチ形の上下窓や六角形の窓を配する。トラス組で真束の上下二ヶ所に貫を通す。小規模な教会堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008127"},{"id":"00012371","register_sub_id":"101","register_pk":"531695","name":"善行寺玄関座敷","kana":"ぜんぎょうじげんかんざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15540278,"lng":136.87452778,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-510","desc":"本堂の東に隣接する玄関座敷。八畳と六畳の座敷を並べ、前に本堂、後ろに庫裏とつなぐ廊下を配する。切妻造本瓦葺平入で、正面中央に間口二間幅で入母屋の式台玄関を構える。妻飾の木連格子や玄関両脇間の花頭窓など、格式ある表構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012371"},{"id":"00012375","register_sub_id":"101","register_pk":"531699","name":"善行寺山門","kana":"ぜんぎょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15506944,"lng":136.8744,"geo_status":"db","era":"宝暦5年(1755)／江戸後期・昭和53年改修","year":1755,"year_source":"db","year_min":1755,"year_max":1755,"year_label":null,"structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"23-514","desc":"境内の南面中央に開く切妻造の四脚門。組物は大斗絵様肘木、妻飾は虹梁大瓶束、軒は一軒疎垂木である。親柱筋の冠木と棟木の間には虹梁を入れ、中備に滝と波を模した躍動感あふれる彫刻の蟇股を入れて意匠を凝らす。境内正面の構えを華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012375"},{"id":"00012372","register_sub_id":"101","register_pk":"531696","name":"善行寺鐘楼","kana":"ぜんぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15515833,"lng":136.87428333,"geo_status":"db","era":"明治29年頃／昭和53年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、瓦葺、面積7.6㎡","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"23-511","desc":"本堂の南西方に位置し、高い乱石積基壇に建つ。方一間、吹放ち形式で、南北棟の入母屋造本瓦葺とする。粽付円柱を貫で固めて台輪を載せ、組物は木鼻付出組の詰組、天井は小組格天井、二軒扇垂木である。均整のとれた禅宗様の鐘楼で、細部意匠も良質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012372"},{"id":"00012373","register_sub_id":"101","register_pk":"531697","name":"善行寺太鼓楼","kana":"ぜんぎょうじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15513056,"lng":136.8745,"geo_status":"db","era":"江戸後期／昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部3階建、瓦葺、建築面積50㎡","structure_material":"木造平屋一部3階建","registered":"2018.05.10(平成30.05.10)","register_no":"23-512","desc":"山門の北東方に建つ。東西棟の切妻造で、屋根中央西寄りに方一間宝形造の楼を載せ、四周に下屋を廻らす。内部は後世に居室化されているが、もと納屋で、西半には中二階や楼への上り口が残る。浄土真宗寺院の伽藍構成を特徴づける太鼓楼として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012373"},{"id":"00012374","register_sub_id":"101","register_pk":"531698","name":"善行寺手水舎","kana":"ぜんぎょうじちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15510833,"lng":136.87434722,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、面積4.5㎡、手水鉢付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"23-513","desc":"山門の北西方に建つ。桁行二・四メートル梁間一・八メートルで、南北棟の切妻造桟瓦葺。角柱を四方転びに立て、内法貫で固め、組物をつくらず、柱頂部で直接桁を受ける。軒は一軒疎垂木である。極めて簡素なつくりの手水舎で、境内に欠かせない構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012374"},{"id":"00012370","register_sub_id":"101","register_pk":"531694","name":"善行寺本堂","kana":"ぜんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15536111,"lng":136.87436667,"geo_status":"db","era":"宝永3年(1706)／文化元年(1804)・昭和51年改修、大正4年増築","year":1706,"year_source":"db","year_min":1706,"year_max":1706,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積277㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-509","desc":"桁行五間梁間五間、入母屋造本瓦葺、向拝一間付の真宗本堂で南面して建つ。内部は外陣の柱を省略し、矢来内にかけて一面に小組格天井を張る。背面の御成りの間は近代の増築。尾張藩の御大工･伊藤平左衛門の手により、虹梁や組物など細部の造作が充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012370"},{"id":"00006495","register_sub_id":"101","register_pk":"107478","name":"専念寺庫裏","kana":"せんねんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券262","lat":35.382847,"lng":136.937744,"geo_status":"db","era":"元禄2／平成16改修","year":1689,"year_source":"db","year_min":1689,"year_max":1689,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0263","desc":"本堂の東に南面して建つ。桁行２１ｍ梁間１１ｍの規模で、切妻造妻入桟瓦葺とする。正面側に土間などを配し、後寄りの床上部は縦に２分する。西側の座敷はトコなどを設ける接客用で、東側は内向の居室とする。江戸中期に遡る庫裏として注目される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006495"},{"id":"00006338","register_sub_id":"101","register_pk":"107321","name":"専念寺本堂","kana":"せんねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券262","lat":35.38289924,"lng":136.93750309,"geo_status":"db","era":"寛文13／平成16改修","year":1673,"year_source":"db","year_min":1673,"year_max":1673,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0262","desc":"境内の北奥に南面して建つ。入母屋造桟瓦葺の７間堂で、正面に１間向拝を付ける。正面１間通りの広縁と、その奥の外陣、そして内陣、脇間からなる浄土宗寺院本堂の特徴的平面となる。内陣まわりの中敷居痕跡や、来迎柱組物絵様など古式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006338"},{"id":"00010789","register_sub_id":"101","register_pk":"201624","name":"善立寺玄関","kana":"ぜんりゅうじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956417,"lng":137.170418,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0432","desc":"本堂の東に接続して建つ。座敷三室に一列を並べ、南北西の三方に縁をまわして、本堂と庫裏を繋ぐ。南面中央には唐破風玄関を張出す。南面廊下を含め、各室は棹縁天井とし、玄関は格天井とする。全体に簡明な中で、玄関廻りの格式を高め、正面構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010789"},{"id":"00010790","register_sub_id":"101","register_pk":"201625","name":"善立寺山門","kana":"ぜんりゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956329,"lng":137.170057,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0433","desc":"境内の西南隅に建つ。間口三・二メートルの高麗門で、冠木上の小壁の建ちが低く、本屋根と控柱上の軒を同高に納める。門扉は下部を銅板張の板壁とし、上部を金剛柵状の格子とする。城門を思わせる古式な姿形を見せ、境内の表構えに重厚な趣を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010790"},{"id":"00010788","register_sub_id":"101","register_pk":"201623","name":"善立寺七面堂","kana":"ぜんりゅうじしちめんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956548,"lng":137.170154,"geo_status":"db","era":"江戸後期／明治後期・昭和44改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0431","desc":"本堂の西に建つ、間口二間半、奥行六間、入母屋造妻入の奥に深い堂で、正面に一間向拝を付す。中古に本堂へと繋がる東側の室を拡張している。内陣まわりの来迎柱上には出組を載せ、極彩色を施して荘厳する。江戸後期における七面大明神信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010788"},{"id":"00010787","register_sub_id":"101","register_pk":"201622","name":"善立寺本堂","kana":"ぜんりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956526,"lng":137.170304,"geo_status":"db","era":"享保19／昭和5・同中期改修","year":1734,"year_source":"db","year_min":1734,"year_max":1734,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0430","desc":"境内に南面して建ち、桁行六間梁間七間、正面一間向拝付、左に七面堂、右に玄関が接続する。平面は正面を広縁、奥を内陣と両脇陣に分け、日蓮宗本堂の特徴を示す。来迎柱のみ円柱として禅宗様須弥壇を置き、上方を極彩色で飾る。内陣の装飾密度を高めた本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010787"},{"id":"00010785","register_sub_id":"101","register_pk":"201620","name":"崇覚寺本堂","kana":"そうがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区橘二丁目601","lat":35.152626,"lng":136.900608,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積323㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0428","desc":"名古屋市街地に境内を構える真宗寺院本堂。標準的な真宗本堂平面で外陣内の柱を省き、比較的規模が大きい。絵様は明瞭かつ伸びやかで、棟梁の八代伊藤平左衛門守富の特徴を示す。架構なども規式に則りながら、小組格天井を全面的に張るなど闊達な造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010785"},{"id":"00009771","register_sub_id":"101","register_pk":"195600","name":"瀧神社本殿","kana":"たきじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市大海字宮ノ前1","lat":34.93855734,"lng":137.54966019,"geo_status":"db","era":"寛文12","year":1672,"year_source":"db","year_min":1672,"year_max":1672,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0392","desc":"覆屋内に納まる一間社流造、こけら葺の社殿で、三方に縁を廻し、正面に木階五級を付す。頭貫には大振りな木鼻を付け、三斗実肘木で桁を受ける。妻飾は虹梁大瓶束。水引虹梁上の中備に透蟇股を備える。海老虹梁の絵様等、細部意匠も時代相応のもので、質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009771"},{"id":"00005078","register_sub_id":"101","register_pk":"106068","name":"長母寺庫裡","kana":"ちょうぼじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市東区矢田町字寺畑2161","lat":35.19693,"lng":136.945145,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積361㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0037","desc":"本堂の東側に建ち，本堂とは廊下および客間と接続し，北西隅に茶室が繋がっている。切妻造・妻入・桟瓦葺で，桁行９間梁間５間の雄大な規模をもち，内部の梁組も重厚である。棟札より大工棟梁は川合半七で，建築年代が明確な庫裡として貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005078"},{"id":"00001418","register_sub_id":"101","register_pk":"102408","name":"長母寺山門","kana":"ちょうぼじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市東区矢田町字寺畑2161","lat":35.196396,"lng":136.944824,"geo_status":"db","era":"18世紀後半","year":1795,"year_source":"estimated","year_min":1751,"year_max":1800,"year_label":"18世紀後半","structure":"木造薬医門、瓦葺、間口4.8m、奥行き1.7m","structure_material":"木造薬医門","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0038","desc":"３間１戸の薬医門で，切妻造・本瓦葺，桁行約４．８ｍと規模も大きい。主柱は五平とし，棟木を板蟇股と蓑束で受け，細部絵様から１８世紀後半と推定される。低い基壇上に建ち，両側に鍵形の築地塀を備えた姿は，地域の景観に欠かせないものとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001418"},{"id":"00001417","register_sub_id":"101","register_pk":"102407","name":"長母寺本堂","kana":"ちょうぼじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区矢田町字寺畑2161","lat":35.19698072,"lng":136.94493814,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積202㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0036","desc":"長母寺は平安末期の創建で，鎌倉中期に臨済宗に改宗し，現在に至っている。無住和尚の説教に発するという「尾張万歳」発祥の地として広く知られている。本堂は方丈形式の建物で，濃尾大地震後の再建であるが，由緒ある寺院の中心建築として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001417"},{"id":"00009971","register_sub_id":"101","register_pk":"196118","name":"知立神社祭文殿及び廻廊","kana":"ちりゅうじんじゃさいもんでんおよびかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01313077,"lng":137.04111012,"geo_status":"db","era":"明治20／大正期・昭和29改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0398","desc":"幣殿と拝殿の間に建つ。中央に四脚門形式で切妻造の祭文殿を構え、左右の廻廊は棟を落としてのばす。また祭文殿の前後に幣殿と拝殿へ両下造の渡りを設け、屋根は総檜皮葺とする。左右対称平面で両翼の廻廊は複廊とし、軸部木太く重厚感のある社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009971"},{"id":"00009972","register_sub_id":"101","register_pk":"196119","name":"知立神社摂社親母神社","kana":"ちりゅうじんじゃせっしゃうばがみしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01305702,"lng":137.04128997,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、檜皮葺、建築面積8.5㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0399","desc":"拝殿の東方に南面して建つ、一間社流造、檜皮葺である。正側面三方に縁を廻らし、軒は二軒繁垂木とする。柱頂を木鼻付の頭貫で固め、実肘木付の三斗を組む。妻飾は虹梁大瓶束とし、束上に三斗を置く。摂社としては規模が大きく、本格的な形式となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009972"},{"id":"00009973","register_sub_id":"101","register_pk":"196120","name":"知立神社茶室","kana":"ちりゅうじんじゃちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01277067,"lng":137.0406301,"geo_status":"db","era":"明治期／昭和43移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0400","desc":"桁行三間半梁間二間半、東西棟の入母屋造桟瓦葺で、東に玄関を設ける。西側の四畳半茶室と三畳の水屋は懸造風に縁を廻らす。茶室は、面皮柱を使い、トコ柱の背側にナンテンの曲材を組込むなど、数寄屋を加味した開放的な構成になる。社叢景観に趣を添える茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009973"},{"id":"00009970","register_sub_id":"101","register_pk":"196117","name":"知立神社拝殿","kana":"ちりゅうじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01298053,"lng":137.04113644,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0397","desc":"桁行六間梁間三間、切妻造妻入、檜皮葺で、間口一間、切妻造の向拝を設けて屋根を重ね、正面性を強調する。平面は前方二間分を土間として奥を板敷とする。縦長に配置され、後方の祭文殿や廻廊とともに、尾張造と呼ばれる社殿配置の三河地方への伝播を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009970"},{"id":"00009969","register_sub_id":"101","register_pk":"196116","name":"知立神社幣殿","kana":"ちりゅうじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01322617,"lng":137.04110417,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、檜皮葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0396","desc":"桁行五間梁間三間、切妻造妻入で、檜皮葺とする。組物を持たず、両妻は二重梁を束で支えて化粧棟木を受け、破風の拝みに猪目懸魚を吊る。内部は板敷の一室で、棹縁天井を張り、長押等に釘隠を打ち、本殿への礼拝空間を整える。簡素な意匠になる幣殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009969"},{"id":"00009968","register_sub_id":"101","register_pk":"196115","name":"知立神社本殿","kana":"ちりゅうじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01334778,"lng":137.0410692,"geo_status":"db","era":"天保2","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0395","desc":"東海道池鯉鮒宿の傍らに位置する。三間社流造、檜皮葺で、正面に板唐戸をたてた身舎内部を前後二室に仕切り、庇部分は左右を板壁として前室状とする。正側面に刎高欄付の縁を付ける。妻飾は虹梁大瓶束形式で、出組で一手持ち出す。規模充実し質も高い本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009968"},{"id":"00013556","register_sub_id":"101","register_pk":"504923","name":"徳雲寺弁天堂","kana":"とくうんじべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県西尾市吉良町吉田八ツ田45","lat":34.79453056,"lng":137.06547222,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積6.3㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"23 － 0559","desc":"本堂東方の基壇上に南面して構え、池の端に建つ。屋根は妻入で、正面入母屋造、背面切妻造とする。規模は正面一間、背側面二間で、奥に仏壇を構えて弁財天を祀る。外壁は下見板張とし正面のみ簓子を付ける。小規模な堂ながら気品を備え、篤い信仰を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013556"},{"id":"00013555","register_sub_id":"101","register_pk":"504922","name":"徳雲寺本堂","kana":"とくうんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県西尾市吉良町吉田伝蔵荒子19","lat":34.79461389,"lng":137.06517778,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"23 － 0558","desc":"布施行者で知られる尼僧颯田本真が開いた、三河湾干拓地に寺地を構える浄土宗寺院。本堂は東面して建ち、北に玄関棟を付す。正面三間側面八間の奥行の深い寄棟造妻入の堂で、四天柱のほかは角柱を用いる。装飾を抑えた素朴な外観で念仏道場の趣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013555"},{"id":"00009293","register_sub_id":"101","register_pk":"194086","name":"徳授寺位牌堂","kana":"とくじゅじいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37781148,"lng":136.93986466,"geo_status":"db","era":"昭和9年／平成18年改修","year":1834,"year_source":"db","year_min":1834,"year_max":1834,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0347","desc":"本堂背面に接続し南北棟で建つ。桁行一二・二メートル梁間五・七メートル、入母屋造及び切妻造桟瓦葺で、内部は南半を位牌堂、北半を開山堂とする。玉石積基礎に建ち、外観は漆喰塗で腰に竪板を張り、開山堂の左右に花頭窓を穿つ。境内景観を構成する位牌堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009293"},{"id":"00009294","register_sub_id":"101","register_pk":"194087","name":"徳授寺玄関","kana":"とくじゅじげんかん","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37755069,"lng":136.93994746,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0348","desc":"本堂東側の庫裏に渡る廊下南面に構える玄関。間口三・八メートル奥行二・七メートル、向唐破風造桟瓦葺である。正面の頭貫と虹梁の間に龍彫刻を飾り、虹梁上の大瓶束には波に菊を表した華やかな笈形を付す。唐破風に吊る鳳凰の兎毛通しとともに見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009294"},{"id":"00009296","register_sub_id":"101","register_pk":"194089","name":"徳授寺山門","kana":"とくじゅじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37705767,"lng":136.93961958,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0350","desc":"境内入口に南北棟で建つ。桁行二・八メートル梁間一・八メートル、切妻造桟瓦葺の薬医門形式で、左右に長さ一・一メートルの袖塀を付し、木部全体を赤色に塗る。古刹の正門に相応しい大型の薬医門で、女梁の絵様や反りの強い垂木形状には古式が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009296"},{"id":"00009295","register_sub_id":"101","register_pk":"194088","name":"徳授寺鐘楼","kana":"とくじゅじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37733559,"lng":136.9399646,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0349","desc":"境内の南東側に建つ鐘楼で、方一間、袴腰付、入母屋造桟瓦葺である。亀甲石積の基壇上に建ち、腰組は二手先で擬宝珠高欄付縁を支持し、上層も二手先組物で小組格天井を張り、軒は二軒繁垂木である。丁寧なつくりの鐘楼で、境内景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009295"},{"id":"00009292","register_sub_id":"101","register_pk":"194085","name":"徳授寺本堂","kana":"とくじゅじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37765348,"lng":136.93982659,"geo_status":"db","era":"明治29年／平成18年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積235㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0346","desc":"境内奥に南面し、桁行一五・一メートル梁間一四・二メートル、入母屋造桟瓦葺である。内部は方丈型六間取形式で正面に広縁を配し、内陣は来迎壁を設けて須弥壇をおき、小組格天井を張る。外陣は室境の柱を省き、欄間は竹の節欄間として広闊な外陣空間を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009292"},{"id":"00010606","register_sub_id":"101","register_pk":"201180","name":"名古屋カテドラル聖ペトロ聖パウロ大聖堂","kana":"なごやかてどらるせいぺとろせいぱうろだいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市東区葵1-1208","lat":35.17275,"lng":136.923908,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋一部2階地下1階建、銅板葺、建築面積928㎡、搭屋及び階段付","structure_material":"鉄骨鉄筋コンクリート造平屋一部2階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0423","desc":"市街地に建つ鉄骨鉄筋コンクリート造の教会堂。ゴシック様式基調で外壁をコンクリート打ち放しとし、双塔に透模様の尖塔を戴く。柱通りの内部に尖頭アーチを架け、外部にバットレスを付して高大な無柱空間を創出し、小屋を現した天井とともに昇高性を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010606"},{"id":"00012553","register_sub_id":"101","register_pk":"367848","name":"七所神社本殿","kana":"ななしょじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市南区笠寺町字天満12","lat":35.095226,"lng":136.934906,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、檜皮葺、建築面積4.0㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0524","desc":"市南部に鎮座し、本殿は境内のほぼ中央に南面して建つ。一間社流造、檜皮葺で、正側面に切目縁を廻して脇障子を立て、正面に木階と浜縁を設ける。三斗の上に肘木を重ねて五斗を並べた組物や波形彫刻の蟇股の正面中備など、小社ながら細部を丁寧につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012553"},{"id":"00014840","register_sub_id":"101","register_pk":"519100","name":"鳴海杻神社祭文殿","kana":"なるみてがしじんじゃさいもんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.34748889,"lng":136.94257778,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0594","desc":"本殿と拝殿間に位置。桁行五間梁間一間切妻造妻入正面向拝一間付の細長い南北棟の前面両脇に棟を直交し桁行三間梁間一間半入母屋造の東西棟を付す。総桟瓦葺。内部は一室の板敷で本殿に向かって床を上げ鏡天井を高く張る。変化のある屋根で社頭景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014840"},{"id":"00014842","register_sub_id":"101","register_pk":"519102","name":"鳴海杻神社社務所","kana":"なるみてがしじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.34699167,"lng":136.94269722,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0596","desc":"境内南東、参道入口の東に位置。平屋建入母屋造平入桟瓦葺、西正面中央に切妻造玄関を付す。正面に廊下を通し、北に床付８畳座敷と６畳次の間を配する。南は廊下を挟んで６畳社務所、台所を東西に並べる。簡素な意匠ながら、境内入口脇の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014842"},{"id":"00014841","register_sub_id":"101","register_pk":"519101","name":"鳴海杻神社拝殿","kana":"なるみてがしじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.34736389,"lng":136.94256389,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0595","desc":"祭文殿前方に位置。桁行三間梁間三間入母屋造桟瓦葺。円柱を地覆、地長押、内法長押、頭貫で固める。組物は台輪上に出三斗とし、軒は２軒繁垂木。内部は一室の板敷で天井は小組格天井を張る。四周を吹放ちとした軽快な建物ながら基壇上に建つ堂々たる拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014841"},{"id":"00014844","register_sub_id":"101","register_pk":"519104","name":"鳴海杻神社藩塀","kana":"なるみてがしじんじゃばんぺい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109-1","lat":35.34723889,"lng":136.94255278,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、銅板葺、延長3.3m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0598","desc":"拝殿と南前方の鳥居間に位置。柱間３間切妻造銅板葺の障壁。両端の円柱は前後の角柱の控柱と貫二段で繋ぐ。柱上部に腕木２段を重ね軒桁を受け、軒は一軒繁垂木。腰長押、内法長押間は連子窓とし腰は縦板張。尾張独特の目隠塀で境内景観のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014844"},{"id":"00014843","register_sub_id":"101","register_pk":"519103","name":"鳴海杻神社弁天堂","kana":"なるみてがしじんじゃべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.3469,"lng":136.942475,"geo_status":"db","era":"元治2年(1865)","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0597","desc":"参道入口の西の湧水池東岸に位置。正面３間側面２間半宝形造桟瓦葺で正面に向拝一間、三方に縁を付す。内部は八畳の１室で、格天井の鏡板に絵画を描く。背面は三分して、中央に金箔貼の宮殿を安置する。境内最古の堂宇で湧水池に浮かぶ点景をつくる弁天堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014843"},{"id":"00014839","register_sub_id":"101","register_pk":"519099","name":"鳴海杻神社本殿","kana":"なるみてがしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.347575,"lng":136.94259167,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0593","desc":"五条川南岸に位置する式内社。１間社入母屋造檜皮葺（銅板仮葺）。正面に千鳥破風、向拝に軒唐破風を付す複雑な屋根構成。組物は出組で腰組は三手先。正面両折桟唐戸に桐紋を付す。脇障子、海老虹梁、蟇股、木鼻、懸魚など随所に彫刻を施す、意匠優秀な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014839"},{"id":"00009761","register_sub_id":"101","register_pk":"195590","name":"日本福音ルーテル岡崎教会教会堂","kana":"にほんふくいんるーてるおかざききょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県岡崎市伝馬通4-54","lat":34.95740632,"lng":137.1726235,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積137㎡","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0382","desc":"木造平屋建で北面し、切妻造妻入、桟瓦葺で、正面玄関に庇を付け、棟上に尖塔を立てて十字架を戴く。内部は三廊式で身廊にキングポストトラスを架け、側廊は間仕切により小部屋に分割できるよう工夫される。白壁と赤屋根のコントラストが映える教会建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009761"},{"id":"00009291","register_sub_id":"101","register_pk":"194084","name":"日本福音ルーテル復活教会","kana":"にほんふくいんるーてるふっかつきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市東区徳川町2303","lat":35.1861601,"lng":136.93213476,"geo_status":"db","era":"昭和28年／昭和35年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋一部2階建、スレート葺、建築面積177㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0345","desc":"木造平屋建、建築面積一七七平方メートル、切妻造スレート葺。南面中央の二階建玄関部に尖塔を建てる。外壁は腰を下見板張、上部をモルタル塗とする。単廊上部にはシザース・トラスの小屋組を見せ、西側内陣上部は十字架形の窓で飾る。明快な意匠の小会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009291"},{"id":"00009464","register_sub_id":"101","register_pk":"194257","name":"如意寺山門","kana":"にょいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.14128821,"lng":137.22627014,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0362","desc":"境内東辺の本堂正面に開く四脚門で、切妻造桟瓦葺。門柱は沓石に立つ円柱で両開の桟唐戸を吊る。控柱は角柱。組物は出三斗とし、中備は冠木上に平三斗、控柱の虹梁上に蟇股とする。妻飾は大瓶束笈形付き。軒は二軒繁垂木とする。内部は小組格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009464"},{"id":"00009463","register_sub_id":"101","register_pk":"194256","name":"如意寺書院","kana":"にょいじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.141544,"lng":137.22560151,"geo_status":"db","era":"江戸後期／明治42年増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0361","desc":"本堂の北に位置する木造平家建、切妻造桟瓦葺。現本堂造営時の仮堂として建設したと伝える。西から上段の間九畳、中の間一二畳、広間一八畳が並び、南から東へ広縁を廻らす。後に北広縁を半間拡幅して西寄りに二室を設け、北西に湯殿と便所を増築している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009463"},{"id":"00009465","register_sub_id":"101","register_pk":"194258","name":"如意寺鐘楼","kana":"にょいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.1411502,"lng":137.22617615,"geo_status":"db","era":"宝暦5年頃","year":1755,"year_source":"db","year_min":1755,"year_max":1755,"year_label":null,"structure":"木造、瓦葺、面積8.8㎡","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0363","desc":"境内南寄り、石積基壇上に建つ入母屋造桟瓦葺。沓石に内転び角柱を立て、腰貫、飛貫、頭貫で固め、台輪を廻らす。組物は出三斗、中備は蟇股。妻飾は虹梁大瓶束。軒は二軒繁垂木。内部は四辺中央から出した腕木上に菱形枠の鏡天井を張り、周囲は格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009465"},{"id":"00009466","register_sub_id":"101","register_pk":"194259","name":"如意寺太鼓楼","kana":"にょいじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.14138814,"lng":137.22617496,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0364","desc":"山門の北西に位置する木造平家建、入母屋造桟瓦葺。屋根中央に棟の向きを違えた入母屋造桟瓦葺の太鼓櫓を載せる。外壁は鉄板張に改修。内部は西側二間半を茶所、東側二間を物置に間仕切る。太鼓櫓外壁は押縁下見板張で、四周を無双窓とする。軒は一軒疎垂木。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009466"},{"id":"00009462","register_sub_id":"101","register_pk":"194255","name":"如意寺本堂","kana":"にょいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.14125133,"lng":137.22568598,"geo_status":"db","era":"文政6年","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積474㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0360","desc":"正面七間の真宗本堂で、入母屋造桟瓦葺、三間幅の向拝がつく。妻飾は二重虹梁大瓶束。外部組物は出三斗で中備を略す。正面から両側面へ廻る広縁と落縁は表から三間位置で止め、飛檐の間との間を板間とする。外陣と矢来内は格天井、内陣は折上格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009462"},{"id":"00010171","register_sub_id":"101","register_pk":"198004","name":"八所神社拝殿","kana":"はっしょじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山2","lat":34.875114,"lng":137.356704,"geo_status":"db","era":"文政9","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0419","desc":"桁行三間梁間二間、入母屋造桟瓦葺。柱頭に頭貫木鼻を付け、三斗に拳鼻と実肘木を組み、中備に蟇股を置く。正背面の中央間を広めて開口部とし、正面両脇間に窓を設ける他は横板壁とする。内部は拭板敷で棹縁天井とする。本殿とともに神仏習合の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010171"},{"id":"00010170","register_sub_id":"101","register_pk":"198003","name":"八所神社本殿","kana":"はっしょじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山2","lat":34.875217,"lng":137.356704,"geo_status":"db","era":"享保9","year":1724,"year_source":"db","year_min":1724,"year_max":1724,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積0.8㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0418","desc":"財賀寺本堂後方の石段上に境内を開く。一間社流造、こけら葺の社殿で、基壇上に建つ。正面二軒、背面一軒の繁垂木とする。妻飾は虹梁大瓶束笈形付とし、束上に大斗と実肘木を置いて化粧棟木を受ける。規模は小さく簡素ながら、江戸時代中期の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010170"},{"id":"00015461","register_sub_id":"101","register_pk":"533476","name":"普門寺十王堂","kana":"ふもんじじゅうおうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74428611,"lng":137.47270278,"geo_status":"db","era":"嘉永5年（1852）／昭和63年頃・平成3年改修","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0613","desc":"本堂の南東、参道に東面して建つ小堂。桁行３間梁間３間、片入母屋造妻入桟瓦葺で、軒は一軒疎垂木、妻飾は虹梁大瓶束とする。堂内は内外陣からなり、外陣北端を格子戸で仕切り、各室板敷で竿縁天井とする。簡素ながら参道に妻飾をみせ境内景観をつくる仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015461"},{"id":"00015462","register_sub_id":"101","register_pk":"533477","name":"普門寺鐘楼門","kana":"ふもんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.744925,"lng":137.47270278,"geo_status":"db","era":"宝永4年（1707）／昭和28年・平成11年改修","year":1707,"year_source":"db","year_min":1707,"year_max":1707,"year_label":null,"structure":"木造2階建、銅板葺、建築面積15㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0614","desc":"境内中央、本坊の前に南面して建つ一間一戸の楼門。上層は桁行３間、梁間３間、入母屋造銅板葺、組物は出組で絵様肘木とし、軒は二軒繁垂木。内部は一室の板敷で、竿縁天井を張り、中央に鐘を吊る。軒出が大きく雄大な姿の鐘楼門で境内の主要な構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015462"},{"id":"00015459","register_sub_id":"101","register_pk":"533474","name":"普門寺大師堂","kana":"ふもんじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74551667,"lng":137.47179444,"geo_status":"db","era":"嘉永7年（1854）／平成2年改修","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0611","desc":"本堂の北に東面して建つ大師堂。宝形造銅板葺の三間堂で正面に一間向拝を付し、三方に縁を廻らす。組物は平三斗で軒は二軒繁垂木。内部は一室で中央後方に来迎柱を立てて須弥壇を配す。天井は格天井で格間に植物を極彩色で描く。軒出大きく軽快な姿の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015459"},{"id":"00015463","register_sub_id":"101","register_pk":"533478","name":"普門寺仁王門","kana":"ふもんじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74408611,"lng":137.47275,"geo_status":"db","era":"江戸中期／平成8年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0615","desc":"境内入口に南面して建つ仁王門。寄棟造銅板葺の八脚門で、組物は二手先、軒は二軒繁垂木。中央間は通路で扉を吊らず、虹梁形内法貫上に彫刻付蟇股を飾る。両脇間の後方に金剛柵と横連子を付し、仁王像一対を安置する。彫刻など細部意匠も端正で上質な八脚門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015463"},{"id":"00015460","register_sub_id":"101","register_pk":"533475","name":"普門寺弁天堂（旧龍神宮）","kana":"ふもんじべんてんどう（きゅうりゅうじんぐう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74561389,"lng":137.47182778,"geo_status":"db","era":"正徳4年（1714）／宝暦5年（1755）・安政3年（1856）移築、平成11年改修","year":1714,"year_source":"db","year_min":1714,"year_max":1714,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0612","desc":"大師堂北の池に東面し、覆屋内に建つ小社。入母屋造杮葺の一間社で正面に千鳥破風を飾り向拝を付す。身舎の組物は出組、軒は二軒繁垂木とし頭貫木鼻に鶏の頭形を飾る。向拝は虹梁形頭貫を龍2頭の尾を絡めて火灯形とするなど、独創的な意匠で装飾豊富な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015460"},{"id":"00015458","register_sub_id":"101","register_pk":"533473","name":"普門寺本堂","kana":"ふもんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74537778,"lng":137.47171389,"geo_status":"db","era":"元禄6年（1693）／昭和31年・平成11年改修","year":1693,"year_source":"db","year_min":1693,"year_max":1693,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0610","desc":"船形山南東斜面に位置する真言宗寺院本堂。境内西側に東面して建つ寄棟造銅板葺の五間堂。前方2間を外陣、後方2間を内陣、背面1間を後陣とし、内陣後方に須弥壇を配す。外陣は桁行３間の虹梁形頭貫を架け、海老虹梁で側柱と繋ぐ架構などに地域的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015458"},{"id":"00008492","register_sub_id":"101","register_pk":"134888","name":"報光寺本堂","kana":"ほうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県江南市古知野町本郷114","lat":35.33806789,"lng":136.87065405,"geo_status":"db","era":"安政2年(1855）／昭和35年改修","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積576㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"23 － 0329","desc":"境内の西南寄りに東面して建つ。桁行二二メートル梁間二六メートル、入母屋造本瓦葺、向拝三間を付ける。大間と外陣、内陣及び余間からなり、周囲一間通りを入側とし、外陣に面した正・側面を吹き放つ。総円柱で、三斗組とするなど本格的仕様になる大型真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008492"},{"id":"00011968","register_sub_id":"101","register_pk":"211106","name":"宝珠院書院","kana":"ほうしゅいんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県西尾市吉良町吉田石池18","lat":34.796049,"lng":137.069196,"geo_status":"db","era":"昭和4年／昭和後期改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"23-507","desc":"本堂北東に縁で接続する。東西棟の寄棟造、桟瓦葺で、上ノ間と次ノ間からなり、四周に広縁を廻らす。上ノ間は、三畳の大床と、一畳の踏込をもつ床脇を備え、いずれも格天井を張る壮大な造り。付書院も備え、格式ある近代和風の書院建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011968"},{"id":"00011969","register_sub_id":"101","register_pk":"211107","name":"宝珠院忠魂堂","kana":"ほうしゅいんちゅうこんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県西尾市吉良町吉田石池18","lat":34.795893,"lng":137.068828,"geo_status":"db","era":"明治36年","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"23-508","desc":"本堂の南西に東面する戦没者慰霊のために建てられた一間堂。宝形造、桟瓦葺で一間向拝を付ける。内部は六畳の奥に厨子を安置し、格天井を張り荘厳する。向拝廻りでは、中備蟇股や手挟の彫刻に日章旗を施すなど時代性を反映した意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011969"},{"id":"00011967","register_sub_id":"101","register_pk":"211105","name":"宝珠院本堂","kana":"ほうしゅいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県西尾市吉良町吉田石池18","lat":34.796027,"lng":137.068983,"geo_status":"db","era":"延宝3年（1675）／安永9年（1780）、昭和後期改修","year":1675,"year_source":"db","year_min":1675,"year_max":1675,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"23-506","desc":"境内北西方に南面する。入母屋造、桟瓦葺の七間堂で、背面に後堂を張り出す。側廻りは柱上に組物を置かず直接軒桁を載せるのに対し、内陣廻りは粽付円柱に台輪を廻らして出組とし、中備蟇股や欄間を彫刻で荘厳する。江戸中期の浄土宗寺院本堂の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011967"},{"id":"00006500","register_sub_id":"101","register_pk":"107483","name":"本光寺山門","kana":"ほんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県岡崎市上青野町字新井1","lat":34.922127,"lng":137.123184,"geo_status":"db","era":"文政10","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造楼門、瓦葺、建築面積25㎡、左右潜戸及び袖塀付","structure_material":"木造楼門","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0250","desc":"本堂の東、通りに面して建つ。入母屋造桟瓦葺の３間１戸楼門。下層の側まわりは開放とし、上層は正・背面中央に桟唐戸を建て、他を格子を嵌めた板壁とする。組物は出組詰組。内部に釈迦如来など三尊を安置。標準的な楼門で、手堅い意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006500"},{"id":"00006499","register_sub_id":"101","register_pk":"107482","name":"本光寺本堂","kana":"ほんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県岡崎市上青野町字新井1","lat":34.922115,"lng":137.122726,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積502㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0249","desc":"境内中央の後方に東面して建つ。入母屋造桟瓦葺で、３間向拝を正面に付ける。典型的な浄土真宗平面で、三方に広縁と落縁を廻し、内陣は後門形式とする。内陣まわりを黒漆地に金箔張の彫刻や絵様で荘厳しており、近代らしい装飾意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006499"},{"id":"00011513","register_sub_id":"101","register_pk":"210541","name":"梵音寺本堂","kana":"ぼんのんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15652111,"lng":137.011535,"geo_status":"db","era":"寛政10年（1798）／昭和後期改修","year":1798,"year_source":"db","year_min":1798,"year_max":1798,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0476","desc":"蓮教寺の塔頭で、境内西側に東面して建つ。桁行三間半、梁間三間、正面入母屋造、背面切妻造、桟瓦葺である。内部は六畳の外陣と四畳の内陣の正側面に縁を廻す。龍の彫刻欄間や向拝虹梁の彫刻など細部にも意を凝らし、境内景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011513"},{"id":"00006768","register_sub_id":"101","register_pk":"107750","name":"真清田神社北門及び透塀","kana":"ますみだじんじゃきたもんおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市真清田1-2-1","lat":35.30788542,"lng":136.80213505,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"北門 木造、銅板葺、間口2.7m、袖塀付、透塀 木造、銅板葺、総延長99m","structure_material":"北門 木造","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0252","desc":"北門は本殿の真北に位置し、北門から透塀が東西方向に繋がる。北門は間口２．７ｍ、切妻造の薬医門。透塀は東側に１０間、西側に１１間、さらに南へ１３間延び、南から３間は屋根を一段下げ、中央に引違戸をたてる。優れた境内景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006768"},{"id":"00006769","register_sub_id":"101","register_pk":"107751","name":"真清田神社祭文殿","kana":"ますみだじんじゃさいもんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市真清田1-2-1","lat":35.307545,"lng":136.802063,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積232㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0251","desc":"本殿の正面、渡殿を介して繋がる。桁行１２ｍ、梁間８．９ｍ、切妻造銅板葺の建物で、身舎は天井が高く、広い一室で、四周に１間幅の下屋を廻す。正面に拝殿、背面に渡殿、両側面に翼廊が付き、複雑な外観を形成するが、細部は簡潔明瞭な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006769"},{"id":"00005618","register_sub_id":"101","register_pk":"106606","name":"真清田神社本殿及び渡殿","kana":"ますみだじんじゃほんでんおよびわたどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市真清田1-2-1","lat":35.30771803,"lng":136.80209918,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積186㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"23 － 0222","desc":"南面して建つ。本殿は三間社流造で，四周に縁を廻し，三斗組，二軒繁垂木，妻飾は二重虹梁である。前面に両下造で，中央格天井，両側間を化粧屋根裏とした渡殿が繋がる。檜材を用い，蟇股など装飾細部を最少限に抑え，優れた比例と荘厳な造形を達成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005618"},{"id":"00010808","register_sub_id":"101","register_pk":"201643","name":"萬福寺山門","kana":"まんぷくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市上重原町本郷27","lat":34.99452,"lng":137.025211,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造、瓦葺、間口5.4m","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0451","desc":"境内東方の正面に構える入母屋造本瓦葺の門。四脚門形式ながら、棟通りの両端より内側に円柱を立てて門口とする。組物は拳鼻付二手先詰組で、さらに各間に蟇股を置く。軒は二軒繁垂木。比較的規模が大きく組物廻りに技巧を凝らし、境内表構えに重厚さを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010808"},{"id":"00010807","register_sub_id":"101","register_pk":"201642","name":"萬福寺鐘楼","kana":"まんぷくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市上重原町本郷27","lat":34.994392,"lng":137.025155,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0450","desc":"境内南東方の切石積基壇上に建つ方一間吹放ち形式の鐘楼で、南北棟の入母屋造桟瓦葺である。礎盤上に内転びに立てる円柱を貫で固め、台輪上の組物は拳鼻付の出組を詰組に、軒は二軒扇垂木とする。禅宗様を基調とし装飾密度の高い鐘楼で、境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010807"},{"id":"00010806","register_sub_id":"101","register_pk":"201641","name":"萬福寺本堂","kana":"まんぷくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知立市上重原町本郷27","lat":34.994502,"lng":137.024563,"geo_status":"db","era":"明治32／平成26改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積603㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0449","desc":"境内中央に東面して建つ。標準的な真宗本堂平面をもつ大型の堂で三間向拝を付す。内陣や余間の折上小組格天井では内陣を二重に折上げ、矢来内や外陣を小組格天井とする。明治期に西三河で活躍した棟梁小野田又蔵の最盛期の作となる、規模雄大で意匠華やかな堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010806"},{"id":"00007211","register_sub_id":"101","register_pk":"108193","name":"湊築島弁天社","kana":"みなとちくしまべんてんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市湊町7-2","lat":34.77193112,"lng":137.38468442,"geo_status":"db","era":"寛政7","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"23 － 0304","desc":"湊町公園の池中の築島に建つ、三間社入母屋造向拝付。屋根は本瓦葺である。三方に擬宝珠高欄付の縁がめぐり、木階３級がつく。外陣は吹放ちで格天井を草木画で飾り、内陣正面に格子戸をたて込み、背面に内々陣を突出する。組物は平三斗実肘木、二軒繁垂木とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007211"},{"id":"00010172","register_sub_id":"101","register_pk":"198005","name":"明眼院旧多宝塔","kana":"みょうげんいんきゅうたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県海部郡大治町大字馬島字北割114","lat":35.174392,"lng":136.820345,"geo_status":"db","era":"慶安2／明治中期・昭和45改修","year":1649,"year_source":"db","year_min":1649,"year_max":1649,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0420","desc":"方三間の多宝塔であったが、濃尾地震後に上層を欠失した。四天柱に直径九寸の円柱、側廻りに七寸の面取角柱を立て、屈曲の強い海老虹梁で繋ぐ。側廻りは拳鼻付三斗で外部出組とし、中備に蟇股と蓑束を置き格天井を張る。尾張地方に多く残る多宝塔の遺例の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010172"},{"id":"00003870","register_sub_id":"101","register_pk":"104860","name":"明治村聖ザビエル天主堂","kana":"めいじむらせいざびえるてんしゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34548462,"lng":136.98969604,"geo_status":"db","era":"明治23／昭和48移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積575㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0104","desc":"もと外周壁を煉瓦造とする木造会堂。平面は三廊式で，身廊壁面を三層構成とするゴシック様式。木製の束ね柱やトリフォリウム，リブ・ヴォールトと，漆喰塗内壁の対比が美しい。外壁にはバットレスを付け，薔薇窓，尖頭アーチ形の開口，小尖塔などで飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003870"},{"id":"00003875","register_sub_id":"101","register_pk":"104865","name":"明治村大明寺聖パウロ教会堂","kana":"めいじむらだいみょうじせいぱうろきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.346291,"lng":136.990967,"geo_status":"db","era":"明治12／平成6移築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0109","desc":"木造平屋建，入母屋造，桟瓦葺。正面に切妻の玄関廊をつけ，鐘楼を載せる。外観は真壁造の和風意匠であるが，内部は三廊式のゴシック様式を実現している。身廊は木製束ね柱と漆喰塗の四分ヴォールトで飾り，側廊には竿縁天井を曲面に張る。大工は大渡伊勢吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003875"},{"id":"00003863","register_sub_id":"101","register_pk":"104853","name":"明治村ハワイ移民集会所","kana":"めいじむらはわいいみんしゅうかいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34386176,"lng":136.9914945,"geo_status":"db","era":"明治22頃／昭和44移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0097","desc":"基督教組合派の岡部次郎牧師が建設した教会。バルーン・フレーム構造の平屋建で，鉄板葺の切妻屋根は軒先で緩勾配とする。隅柱付の下見板張で上げ下げ窓を開く。正面軒高にコーニスを飾り，換気口や入口上ペディメントと共に反復する三角形で意匠をまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003863"},{"id":"00009770","register_sub_id":"101","register_pk":"195599","name":"八平神社玉垣","kana":"やひらじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県新城市出沢字八ノ平102-1","lat":34.94255304,"lng":137.5356601,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造、瓦葺、延長28m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0391","desc":"本殿の四方を囲み、正面五間、側面四間、両下造、桟瓦葺である。正面中央間に両折れの格子戸を備える。そのほかは土台上の柱を腰貫、内法貫で固め、竪板壁を張る。山林の中の神域を画す玉垣で、本殿と一体となって森厳な雰囲気の境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009770"},{"id":"00009769","register_sub_id":"101","register_pk":"195598","name":"八平神社本殿","kana":"やひらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字八ノ平102-1","lat":34.94253626,"lng":137.53571293,"geo_status":"db","era":"元禄13／大正7改修","year":1700,"year_source":"db","year_min":1700,"year_max":1700,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.7㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0390","desc":"龍泉寺東側の境内に位置する銅板葺の流造社殿。身舎は間口一間、奥行二間で、内陣を三室に区画する。庇柱は角柱として木階を設け、正側面に縁を廻らす。背面柱筋に脇障子をたて、琵琶板に格狭間様の彫刻を飾る。江戸中期の当地域における小規模社殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009769"},{"id":"00009765","register_sub_id":"101","register_pk":"195594","name":"龍泉寺開山堂及び位牌堂","kana":"りゅうせんじかいざんどうおよびいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.94228737,"lng":137.53556207,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0386","desc":"本堂の背面に渡殿を介して接続する。切妻造桟瓦葺で、腰高に簓子下見板を張る。内部は渡殿から奥に位牌堂、開山堂を配し、徐々に床高を上げる構成をもつ。位牌堂は左右に位牌壇を設え、開山堂は、入口や後部の仏壇の要所に絵様虹梁を架け渡し、漆塗などで荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009765"},{"id":"00009766","register_sub_id":"101","register_pk":"195595","name":"龍泉寺観音堂及び御茶堂","kana":"りゅうせんじかんのんどうおよびおちゃどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.94207036,"lng":137.53560347,"geo_status":"db","era":"観音堂 文政5 御茶堂 昭和10","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0387","desc":"本堂の南西方に東面して建つ。観音堂は方三間の小規模な堂で、後方一間を仏壇として三十三観音を祀る。御茶堂は観音堂南側に接続し、観音堂参拝者に茶を接待する場となっている。総体に簡素な建築ながら当地域における観音信仰の一端を伺い知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009766"},{"id":"00009767","register_sub_id":"101","register_pk":"195596","name":"龍泉寺庫裏","kana":"りゅうせんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.9422374,"lng":137.53579478,"geo_status":"db","era":"天保14／平成19改修","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積148㎡","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0388","desc":"本堂の東に南北棟で建つ切妻造桟瓦葺で、本堂との間に南向きの玄関と二室をおいて接続する。中央に立てた大黒柱の北側に四室を、南側の旧土間には調理場などを配する。伽藍景観の一角を担うとともに、江戸末期の地方における禅院庫裏の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009767"},{"id":"00009768","register_sub_id":"101","register_pk":"195597","name":"龍泉寺鐘楼","kana":"りゅうせんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.9420618,"lng":137.5358576,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造、瓦葺、面積6.7㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0389","desc":"庫裏の南方に東西棟で建つ。方一間吹放ちの鐘楼で、基壇上に几帳面取角柱を内転びに立て、腰貫と内法貫を通し、虹梁状の頭貫と台輪で固める。組物は三斗で、中備を省く。入母屋造桟瓦葺で、軒は一軒繁垂木、天井は格天井を張る。伝統的な形式の吹放ち鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009768"},{"id":"00009764","register_sub_id":"101","register_pk":"195593","name":"龍泉寺本堂","kana":"りゅうせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.94220028,"lng":137.53567343,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0385","desc":"山あいに所在する境内の奥に、南面して建つ。入母屋造桟瓦葺で、正面中央間に虹梁を架ける。内部は六間取の前面に広縁を通す平面で、中列奥の内陣に須弥壇を構え、大間との境は円柱を絵様虹梁で繋ぎ、欄間に雲龍や唐獅子の彫刻を飾るなど華やかな意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009764"},{"id":"00011510","register_sub_id":"101","register_pk":"210538","name":"蓮教寺庫裏","kana":"れんきょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15635306,"lng":137.01204111,"geo_status":"db","era":"宝暦13年（1763）／昭和後期改修","year":1763,"year_source":"db","year_min":1763,"year_max":1763,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積249㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0473","desc":"本堂の東側にある庫裏。桁行九間半、梁間四間、切妻造桟瓦葺、妻入で、側背面に下屋が付く。南を土間とし、北は東西三列の居室を並べ、仏間はトコと付書院を構える。外観は真壁漆喰塗で、妻面は小屋束や梁を現す。簡素な造りながら、風格ある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011510"},{"id":"00011512","register_sub_id":"101","register_pk":"210540","name":"蓮教寺山門及び脇塀","kana":"れんきょうじさんもんおよびわきべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15621611,"lng":137.01168111,"geo_status":"db","era":"文化9年（1812）／平成12年改修","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"山門 木造、瓦葺、間口3.7m 脇塀 木造、瓦葺、総延長23m","structure_material":"山門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"23-0475","desc":"本堂正面の参道に建つ四脚門。切妻造、本瓦葺で、両脇に真壁漆喰塗の脇塀が矩折れに続く。主柱は丸柱、控柱は几帳面取の角柱で、妻面は笈形付き大瓶束で棟木を受ける。軸部は木太く重厚な造りで、随所に意匠を凝らした彫刻で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011512"}];
